// Rulebooks: for each case type in the library, the legal tests in the order an adjudicator applies them, the standard,
// the key precedents and the traps that sink cases. Lincoln is given the rulebook whenever it reads, checks or drafts a
// case of that type, and the official text of the cited provisions comes from the law library (law.ts), so the wording
// of the law is always the published text, not this summary.
//
// Drafted 2026-11-22 from the INA, 8 CFR, 20 CFR 656, 22 CFR and published precedent, after the first real case test
// (tests/aao) showed Lincoln missing type specific tests. To be reviewed by an immigration attorney. Policies that change
// often (fees, DACA litigation, TPS designations, parole programs, H-1B selection) say "check current" on purpose.

import { OFFICIAL_CODES } from "./codes";
import { EVIDENCE } from "./rulebook-evidence";

export type Rulebook = { cites: string[]; rules: string };

const GENERAL = "Burden on the filer, preponderance of the evidence (Matter of Chawathe, 25 I&N Dec. 369). Eligibility must exist at filing and through adjudication (8 CFR 103.2(b)(1)); evidence of later events cannot cure a petition. Assertions need corroboration; statements in a brief are not evidence. Non precedent decisions and other people's approvals do not bind USCIS.";

const R: Record<string, Rulebook> = {
  // Employment based nonimmigrant
  "H-1B": { cites: ["8 CFR 214.2(h)(4)", "INA 101(a)(15)(H)", "INA 214(i)", "INA 214(g)"], rules: `1. Specialty occupation (8 CFR 214.2(h)(4)(ii), (iii)(A)): the position itself must normally require at least a bachelor's degree in a specific specialty directly related to the duties, or its equivalent; a general degree or "any degree" requirement fails. Show it through the occupation's normal requirement (Occupational Outlook Handbook, O*NET), industry norm, the employer's own practice, or duties so specialized and complex. Duties must be detailed, not generic.
2. Beneficiary qualified (h)(4)(iii)(C), (D): US or equivalent foreign degree in the specialty, or equivalence by education and experience (three years of specialty experience for each year of missing education, credential evaluation, AACRAO EDGE as reference). Licensed occupations need the license.
3. LCA (ETA-9035) certified for the right occupation, wage level, worksite and dates; the offered wage meets the LCA. Third party worksites need proof of actual work and itinerary.
4. Bona fide employer and job, cap subject or a real cap exemption (institution of higher education, affiliated nonprofit, nonprofit or government research organization: INA 214(g)(5)); selection in the lottery for cap cases (check current selection rules).
5. Maintenance of status for extensions and changes. Traps: nursing positions (only advanced practice nurses generally qualify; registered nurses generally do not, nursing assistants never), market research analyst and similar generalist jobs, entry level wage with complex duties claim, inconsistent duties between letter, LCA and organization chart.` },
  "H-1B1": { cites: ["INA 101(a)(15)(H)", "8 CFR 214.2(h)(4)"], rules: "Chile and Singapore nationals; specialty occupation standard as H-1B (degree in a specific specialty normally required), LCA required, temporary intent required (no dual intent), usually obtained at a consulate; one year stays renewable. Check nationality and that the job meets the H-1B specialty occupation test." },
  "E-3": { cites: ["INA 101(a)(15)(E)", "8 CFR 214.2(e)"], rules: "Australian nationals in a specialty occupation (same degree test as H-1B), LCA required, two year periods, nonimmigrant intent required. Spouse may work incident to status. Check: nationality, specialty occupation, degree equivalence, LCA match." },
  "H-2A": { cites: ["8 CFR 214.2(h)(5)", "20 CFR 655.100"], rules: "Temporary or seasonal agricultural labor; a temporary labor certification from DOL first (20 CFR 655 subpart B); employer obligations (housing, transport, three fourths guarantee, AEWR wage); workers from eligible countries; petition within the certified dates. Traps: year round work presented as seasonal, joint employer issues, recruitment of US workers not done in good faith." },
  "H-2B": { cites: ["8 CFR 214.2(h)(6)", "20 CFR 655.1"], rules: "Temporary non agricultural need: one time occurrence, seasonal, peakload or intermittent (8 CFR 214.2(h)(6)(ii)(B)), normally under one year; temporary labor certification from DOL; cap and supplemental visas (check current); eligible countries list. The employer's need must be temporary even if the job is not. Traps: permanent need disguised as peakload, prior years' payroll showing year round staffing." },
  "H-3": { cites: ["8 CFR 214.2(h)(7)"], rules: "Training not available in the home country, not productive employment except incidental, benefits a career abroad, a structured training program with hours of classroom and on the job training. Traps: training that is really work, trainee already has substantial expertise." },
  "L-1A": { cites: ["8 CFR 214.2(l)(1)(ii)", "8 CFR 214.2(l)(3)", "INA 101(a)(44)"], rules: `1. Qualifying relationship between the US and foreign entities (parent, branch, subsidiary, affiliate), with ownership and control documented; both doing business.
2. One continuous year of full time employment abroad in the last three years in a managerial, executive or specialized knowledge role (time in the US does not interrupt but does not count).
3. US role primarily managerial or executive (INA 101(a)(44)): personnel manager over supervisory, professional or managerial staff, or function manager of an essential function (Matter of G- Inc., Adopted Decision 2017-01); executive directs management and sets goals. A first line supervisor of non professionals is not a manager. Duties must be detailed with time breakdown; staffing must relieve the person from operational work (Family Inc. v. USCIS; Fedin Bros. v. Sava). Small size counts with reasonable needs, but non managerial work still must be done by someone.
4. New office (8 CFR 214.2(l)(3)(v)): physical premises secured, business plan showing support for a manager within one year, foreign entity's ability to fund; one year initial approval. Traps: vague duties paraphrasing the statute, organization charts that do not match payroll, absent subordinates.` },
  "L-1B": { cites: ["8 CFR 214.2(l)(1)(ii)(D)", "INA 214(c)(2)(B)"], rules: "Specialized knowledge: special knowledge of the company's product, service, research, equipment, techniques or processes, or advanced knowledge of its processes and procedures, distinct or uncommon compared with others in the industry or the company (Matter of L-S-, Adopted Decision 2015-01; USCIS Policy Manual). Plus qualifying relationship and one year abroad in the last three. Off site placement restrictions (L-1 Visa Reform Act): the worker must be controlled by the petitioner and the placement must not be labor for hire. Traps: knowledge any experienced worker in the field has, no comparison with peers." },
  "I-129S": { cites: ["8 CFR 214.2(l)(4)", "8 CFR 214.2(l)(5)"], rules: "Blanket L: the organization's blanket approval must be valid; the beneficiary must meet L-1A or L-1B requirements (for blanket L-1B, a specialized knowledge professional); filed at the consulate with I-129S; consular officer can require an individual petition. Check the blanket's entities include the employing entity." },
  "O-1A": { cites: ["8 CFR 214.2(o)(3)(ii)", "8 CFR 214.2(o)(3)(iii)", "8 CFR 214.2(o)(5)", "INA 101(a)(15)(O)"], rules: `1. A major internationally recognized award, or at least three of the eight criteria (8 CFR 214.2(o)(3)(iii)(B)): nationally or internationally recognized prizes; membership requiring outstanding achievement judged by experts; published material ABOUT the person in professional, major trade or major media, with title, date and author (material about the employer or the product does not count); judging the work of others in the same or an allied field; original contributions of major significance (influence beyond the person's employer); scholarly articles; critical or essential employment for distinguished organizations; high salary compared with others in the field. Comparable evidence only if a criterion does not readily apply (o)(3)(iii)(C).
2. Totality: sustained national or international acclaim, among the small percentage at the very top of the field (o)(3)(ii). Meeting three criteria is necessary, not sufficient.
3. Advisory opinion (consultation) from a peer group or labor organization (o)(5), or a statement that none exists; itinerary and contracts for multiple engagements; agent petitions. Traps: press about the company, judging in an unrelated field, letters from colleagues asserting importance without independent proof, events after filing.` },
  "O-1B": { cites: ["8 CFR 214.2(o)(3)(iv)", "8 CFR 214.2(o)(3)(v)", "INA 101(a)(15)(O)"], rules: "Arts: distinction, a high level of achievement substantially above that ordinarily encountered, renowned or leading in the field; a significant national or international award nomination or receipt, or three of six criteria (lead or starring role in distinguished productions or events, national or international recognition in published material, lead role for distinguished organizations, record of major commercial or critically acclaimed successes, significant recognition from organizations, government or experts, high salary). Motion picture and television: extraordinary achievement, a higher standard. Consultation with the union and management organization required. Traps: local recognition, roles that are not lead or starring, press without dates or authors." },
  "O-2": { cites: ["8 CFR 214.2(o)(4)"], rules: "Accompanies an O-1 artist or athlete for a specific event; integral part of the O-1's performance; critical skills and experience not of a general nature not possessed by US workers; for film, a pre existing long standing working relationship. Separate petition; consultation required." },
  "P-1": { cites: ["8 CFR 214.2(p)(4)"], rules: "P-1A athletes: internationally recognized level of performance, two of the listed criteria (major league, national team, significant honors, ranking, letters from league officials and experts); P-1B entertainment groups: group recognized internationally, 75 percent of members with the group for at least a year. Consultation required. Traps: individual entertainers (not eligible for P-1B), recognition that is only national for P-1B." },
  "P-2": { cites: ["8 CFR 214.2(p)(5)"], rules: "Reciprocal exchange program between a US organization and a foreign one; comparable skills and terms; consultation with the labor organization." },
  "P-3": { cites: ["8 CFR 214.2(p)(6)"], rules: "Culturally unique program: performer or group develops, interprets, represents, coaches or teaches a unique or traditional ethnic, folk, cultural, musical, theatrical or artistic performance; affidavits from experts and evidence the performances are culturally unique; consultation." },
  "E-1": { cites: ["8 CFR 214.2(e)", "INA 101(a)(15)(E)"], rules: "Treaty country nationality of the trader and at least 50 percent of the enterprise; substantial trade (continuous flow of numerous transactions); more than 50 percent of the international trade is between the US and the treaty country; employee must be executive, supervisory or essential skills. Intent to depart when status ends." },
  "E-2": { cites: ["8 CFR 214.2(e)", "INA 101(a)(15)(E)", "22 CFR 41.51"], rules: "Treaty nationality (investor and at least 50 percent ownership); investment at risk and irrevocably committed, substantial in proportion to the business cost; a real and operating enterprise, not marginal (capacity to generate more than a minimal living or a significant economic impact); investor develops and directs (at least 50 percent ownership or operational control); lawful source of funds traced. Employees: same nationality, executive or supervisory or essential skills. Traps: funds in a bank account not committed, loans secured by the business assets, start up with no premises or contracts." },
  "TN": { cites: ["8 CFR 214.6"], rules: "Canadian or Mexican citizen; profession on the USMCA list (Appendix 1603.D.1) with its stated minimum qualification; prearranged professional employment, not self employment; temporary intent. Traps: job duties that do not match the listed profession (management consultant, engineer used for technician roles), degree in an unrelated field." },
  "R-1": { cites: ["8 CFR 214.2(r)"], rules: "Member for at least two years of a religious denomination with a bona fide nonprofit religious organization in the US; coming to work as a minister or in a religious occupation or vocation at least 20 hours a week; organization is tax exempt (or affiliated); compensation or self support documented; site inspection possible. Traps: secular duties (administration, maintenance), membership not continuous." },
  "Q-1": { cites: ["8 CFR 214.2(q)"], rules: "International cultural exchange program approved by USCIS; the work has a cultural component that shares the history, culture and traditions of the home country; participant at least 18 and able to communicate the culture; wages and conditions comparable to local workers; up to 15 months." },
  "I-129CW": { cites: ["8 CFR 214.2(w)"], rules: "CNMI only transitional worker: employer in the CNMI, position not filled by US workers, legitimate business, numerical limits and fees (check current extension of the program); worker admissible." },
  "I-941": { cites: ["8 CFR 212.19"], rules: "International entrepreneur parole: start up formed in the US within five years, entrepreneur owns at least 10 percent with a central and active role; qualified investment from US investors or government grants at the thresholds in 8 CFR 212.19 (check current inflation adjusted amounts), or partial qualification plus other compelling evidence of rapid growth and job creation; significant public benefit; discretion." },
  "I-907": { cites: ["8 CFR 106.4", "INA 286(u)"], rules: "Premium processing: available only for the listed form types and classifications (check current list); USCIS acts within the stated period (approval, denial, RFE or NOID, or investigation notice); the fee is refunded if it does not. It speeds processing; it does not change eligibility." },

  // Employment based immigrant
  "EB-1A": { cites: ["8 CFR 204.5(h)(2)", "8 CFR 204.5(h)(3)", "8 CFR 204.5(h)(4)", "8 CFR 204.5(h)(5)", "INA 203(b)(1)(A)"], rules: `Two step review (Kazarian v. USCIS, 596 F.3d 1115): 1. A one time major internationally recognized award, or three of the ten criteria at 8 CFR 204.5(h)(3): (i) lesser national or international prizes for excellence; (ii) membership requiring outstanding achievement judged by recognized experts; (iii) published material ABOUT the person in professional, major trade or major media, with title, date and author (publisher is not author; the outlet's status needs objective evidence such as circulation in context, not its own claims); (iv) judging the work of others in the same or an allied field, actually participated; (v) original contributions of major significance in the field (influence on the field as a whole, not just one employer); (vi) scholarly articles; (vii) display at artistic exhibitions; (viii) leading or critical role for distinguished organizations; (ix) high salary relative to others in the field; (x) commercial success in the performing arts. Comparable evidence only where a criterion does not readily apply (h)(4).
2. Final merits: sustained national or international acclaim and among the small percentage at the very top of the field (h)(2). If fewer than three criteria are met, the final merits step is not reached.
3. Continue work in the field in the US (h)(5) and prospective benefit. Evidence from after the filing date cannot count (Matter of Katigbak). Traps: athletes or coaches with dated awards, judging volunteer or local events, claims of influence with no corroboration, self description by outlets.` },
  "EB-1B": { cites: ["8 CFR 204.5(i)", "INA 203(b)(1)(B)"], rules: "International recognition as outstanding in a specific academic area; at least three years of teaching or research experience (graduate research counts only if the degree was obtained and the work is recognized as outstanding); two of six criteria (major prizes, membership requiring outstanding achievement, published material about the work, judging, original research contributions, scholarly books or articles in international journals); a job offer for a tenured or tenure track teaching position or a permanent research position (a private employer needs at least three full time researchers and documented accomplishments). Final merits as for EB-1A." },
  "EB-1C": { cites: ["8 CFR 204.5(j)", "INA 101(a)(44)", "INA 203(b)(1)(C)"], rules: `1. Employed abroad for at least one year in the three years before filing (or before entry as a nonimmigrant for the same employer, Matter of S-P-, Inc., Adopted Decision 2018-01) in a managerial or executive capacity.
2. Qualifying relationship (same employer, parent, branch, subsidiary, affiliate) and the US employer doing business for at least one year.
3. US position primarily managerial or executive (INA 101(a)(44)): all four elements of the definition, then primarily managerial in daily duties, with a detailed description and time breakdown, the organization chart, subordinates' duties and education (professionals need a bachelor's to qualify as professional), staffing that relieves the beneficiary from operational work, at filing and through adjudication (Family Inc. v. USCIS; Fedin Bros. v. Sava). A first line supervisor of non professionals is not a manager. Function manager needs an essential function and others to perform it.
4. Ability to pay (8 CFR 204.5(g)(2)). Prior L-1A approvals do not bind the immigrant petition. Traps: materially changed duties in an RFE response, contractors claimed as managers, staff departures, a second location with no staff.` },
  "EB-2 NIW": { cites: ["8 CFR 204.5(k)", "INA 203(b)(2)"], rules: `1. EB-2 eligibility: advanced degree (US master's or higher, or bachelor's plus five years of progressive post degree experience) or exceptional ability (three of six criteria at 8 CFR 204.5(k)(3)(ii), then a final merits look at expertise significantly above that ordinarily encountered).
2. National interest waiver under Matter of Dhanasar, 26 I&N Dec. 884: (a) the specific proposed endeavor (not the occupation or field) has substantial merit and national importance (broader implications, national or global impact, significant potential to employ US workers or substantial positive economic effects, especially in depressed areas); (b) the person is well positioned to advance it (education, skills, record of success, a plan, progress, interest of stakeholders); (c) on balance waiving the job offer and labor certification benefits the US.
3. If prong one fails, the others are not reached. Traps: describing a job rather than an endeavor, relying on the importance of the field (AI, healthcare) instead of the endeavor's impact, letters about past work offered for national importance, unsupported economic claims.` },
  "EB-2": { cites: ["8 CFR 204.5(k)", "8 CFR 204.5(g)", "20 CFR 656.17"], rules: "Approved labor certification (PERM) unless Schedule A; the beneficiary met every requirement of the certified job by the priority date (degree type and field, experience gained before the job with this employer unless substantially different); experience letters with name, title, dates and duties (8 CFR 204.5(g)(1)); advanced degree or equivalent; employer's continuing ability to pay the proffered wage from the priority date (net income, net current assets, or wages already paid; 8 CFR 204.5(g)(2))." },
  "EB-3": { cites: ["8 CFR 204.5(l)", "8 CFR 204.5(g)"], rules: "Approved labor certification; skilled worker (job requiring at least two years of training or experience, beneficiary meets it), professional (US bachelor's or foreign equivalent single degree, no combination of lesser degrees), or other worker (less than two years); beneficiary qualified by the priority date; ability to pay from the priority date. Traps: equivalency degrees for the professional category, experience gained with the sponsor in the same job." },
  "I-140": { cites: ["8 CFR 204.5"], rules: "Immigrant petition for a worker: identify the category (EB-1A, EB-1B, EB-1C, EB-2, EB-2 NIW, EB-3) and apply that category's rulebook. Common to all employer petitions: ability to pay from the priority date, beneficiary qualifications as of the priority date, bona fide job offer." },
  "I-140G": { cites: ["8 CFR 204.5"], rules: "Gold Card petition: a new program; check the current regulations, eligibility, fees and USCIS guidance before advising, and verify every requirement against the official text. Treat as unsettled law." },
  "EB-4": { cites: ["8 CFR 204.5(m)", "INA 101(a)(27)"], rules: "Special immigrants (I-360). Religious workers (8 CFR 204.5(m)): two years of continuous membership and qualifying religious work immediately before filing, lawful status if in the US, compensated position, at least 35 hours a week, site inspection. Other EB-4 groups follow their own provisions: Afghan and Iraqi SIVs, broadcasters for the US Agency for Global Media, retired international organization (G-4) employees and family, armed forces members with 12 years of service (or six and a reenlistment), Panama Canal employees, certain physicians, and SIJS." },
  "EB-5": { cites: ["8 CFR 204.6", "INA 203(b)(5)"], rules: "Investment at the current threshold (check current amounts; reduced in targeted employment areas and rural areas), at risk, in a new commercial enterprise; lawful source and path of funds traced in full; ten full time jobs for qualifying employees (direct for standalone, direct or indirect through a regional center); investor's role in policy or management. Traps: gifts or loans not traced to a lawful source, funds held in escrow without risk, redemption guarantees." },
  "I-526": { cites: ["8 CFR 204.6"], rules: "Standalone investor petition: as EB-5, with direct job creation only, a comprehensive business plan (Matter of Ho, 22 I&N Dec. 206), and lawful source of every dollar." },
  "I-526E": { cites: ["8 CFR 204.6", "INA 203(b)(5)(E)"], rules: "Regional center investor petition (EB-5 Reform and Integrity Act of 2022): investment in an approved project of a designated regional center, lawful source and path of funds, at risk, job creation (indirect allowed), compliance with the Act's integrity provisions. Check the project's I-956F status." },
  "I-829": { cites: ["8 CFR 216.6", "INA 216A"], rules: "Remove conditions on an investor's residence: filed in the 90 days before the second anniversary; investment sustained, the enterprise established and the required jobs created or expected within a reasonable time; no material change that defeats eligibility; source of funds may be revisited." },
  "I-956": { cites: ["INA 203(b)(5)(E)"], rules: "Regional center designation and project filings under the EB-5 Reform and Integrity Act: geographic area, economic analysis, compliance and integrity requirements, annual filings. Related filings: I-956F project applications, I-956G annual statements, I-956H bona fides of people involved, I-956K promoter registration. Check current USCIS guidance; specialist area." },
  "I-485 Supplement J": { cites: ["INA 204(j)", "8 CFR 245.25"], rules: "Confirms the bona fide job offer for an employment based adjustment; for portability under INA 204(j), the I-485 pending 180 days or more and the new job in the same or a similar occupational classification as the I-140 job (compare duties, skills, education, wages)." },

  // Labor certification
  "PERM": { cites: ["20 CFR 656.10", "20 CFR 656.17", "20 CFR 656.40"], rules: "Prevailing wage determination first; recruitment within 180 days before filing and at least 30 days before (job order 30 days, two Sunday print ads, for professional jobs three more steps; notice of filing posted 10 business days); minimum requirements must be the employer's actual minimum and normal for the occupation unless business necessity (20 CFR 656.17(h)); experience gained with the employer in a substantially comparable job cannot be required; lawful job related reasons for rejecting each US applicant; recruitment report. Bona fide job opening, no undue influence of the beneficiary. Traps: tailored requirements, foreign language requirement without business necessity, missing recruitment proof in an audit." },
  "ETA-9141": { cites: ["20 CFR 656.40"], rules: "Prevailing wage request: correct occupation (SOC code) and wage level for the duties and requirements; requirements beyond the normal for the occupation raise the level; can be reviewed by the National Prevailing Wage Center. The offered wage must meet the determination." },
  "ETA-9089": { cites: ["20 CFR 656.17"], rules: "PERM application: every answer consistent with the recruitment and job requirements; the beneficiary's qualifications as stated must meet the minimum requirements by the time of hire; retention of the audit file five years. See PERM rulebook." },
  "ETA-9035": { cites: ["20 CFR 655.700", "20 CFR 655.730"], rules: "Labor condition application: correct occupation, wage level and worksites; employer attests to wage, working conditions, no strike, and notice; public access file; H-1B dependent employer extra attestations. The petition must match the LCA." },
  "ETA-9142": { cites: ["20 CFR 655.1", "20 CFR 655.100"], rules: "Temporary labor certification (H-2A or H-2B): temporary need, recruitment of US workers, wage offer, employer obligations; job order and notice; filing timelines. See H-2A and H-2B rulebooks." },
  "PERM audit": { cites: ["20 CFR 656.20", "20 CFR 656.21"], rules: "Audit response within 30 days: full recruitment documentation, resumes and reasons for rejection, business necessity proof; supervised recruitment if ordered. Failure to respond is abandonment and can bar future filings." },

  // Family based
  "I-130": { cites: ["8 CFR 204.1", "8 CFR 204.2", "INA 201(b)(2)(A)(i)", "INA 203(a)", "INA 204(c)"], rules: `1. Petitioner's status (US citizen or LPR) and the qualifying relationship by primary evidence (birth, marriage certificates); legitimation or step relationship rules where relevant.
2. Marriage: valid where celebrated and bona fide at inception (intent to establish a life together; joint finances, residence, children, affidavits). All prior marriages of both spouses legally ended before this one (a marriage during an undissolved prior marriage is void). Marriage during removal proceedings needs clear and convincing proof of bona fides or two years outside the US (INA 204(g), 245(e)).
3. INA 204(c) bar: a prior marriage entered to evade immigration law bars any later petition if substantial and probative evidence shows it (Matter of Tawfik); this bar does not apply to U or T applications.
4. Category and priority date: immediate relative or preference F1, F2A, F2B, F3, F4; CSPA age (INA 203(h)) for children. Adam Walsh Act bar for petitioners with specified offenses against minors. Traps: overlapping marriages, divorce decrees not final, siblings needing a common parent proven.` },
  "I-129F": { cites: ["8 CFR 214.2(k)", "INA 214(d)"], rules: "US citizen petitioner; both legally free to marry; met in person within the two years before filing (waiver only for extreme hardship or strict religious or cultural custom); bona fide intent to marry within 90 days of admission; IMBRA disclosure of specified criminal history and the multiple filer limits; international marriage broker rules. Children under 21 as K-2." },
  "K-3": { cites: ["8 CFR 214.2(k)(7)"], rules: "Spouse of a US citizen with a pending I-130; rarely used because USCIS usually decides the I-130 first and the case proceeds as an immigrant visa. Check whether the I-130 is already approved." },
  "I-751": { cites: ["8 CFR 216.4", "8 CFR 216.5", "INA 216"], rules: "Joint petition in the 90 days before the second anniversary of conditional residence, showing the marriage was entered in good faith (not that it continues happily); late filing needs good cause. Waivers (8 CFR 216.5): good faith marriage ended by divorce or annulment (or death), battery or extreme cruelty by the spouse, or extreme hardship from removal arising in the conditional period. Interview possible; failure to file ends status. Traps: filing jointly after separation, using the waiver before the divorce is final (it can be filed and then updated)." },
  "I-360 widow": { cites: ["8 CFR 204.2(b)", "INA 201(b)(2)(A)(i)"], rules: "Widow or widower of a US citizen: married at the time of death (legally, not divorced or separated by decree), petition within two years of the death, not remarried; bona fide marriage. Children included." },
  "I-730": { cites: ["8 CFR 207.7", "8 CFR 208.21"], rules: "Refugee or asylee follow to join for spouse and unmarried children under 21: relationship existed when the principal was admitted or granted asylum (child in utero counts); filed within two years of admission or grant (extendable for humanitarian reasons); principal still a refugee or asylee or became LPR on that basis. Persecutors barred." },
  "I-864": { cites: ["8 CFR 213a.2", "INA 213A"], rules: "Required for family immigrants and some employment cases; sponsor income at least 125 percent of the federal poverty guidelines for the household size (100 percent for active military sponsoring spouse or child), using the most recent tax year; assets at three times the shortfall (five times generally; once for a spouse or child of a citizen); joint sponsor if needed; I-864A for household members. Household size counts the sponsor, dependents, the immigrants and prior sponsored immigrants still under obligation. Check current guidelines. Variants: I-864EZ (one sponsor using only salary), I-864A (household member), and the exemption for those who need none (40 quarters of work, a child who will become a citizen on entry); the sponsor reports address changes on I-865." },
  "I-134": { cites: ["8 CFR 214.1"], rules: "Declaration of financial support for nonimmigrants or parole programs; shows the supporter's income and assets and relationship; not legally binding like the I-864. Check the program it is used for." },
  "I-600": { cites: ["8 CFR 204.3"], rules: "Orphan from a non Hague country: child under 16 at filing (18 for siblings), meets the orphan definition (death or disappearance, abandonment, separation or loss of both parents, or a sole or surviving parent unable to care and who irrevocably releases), adopted abroad or to be adopted in the US, approved home study, prospective parents eligible (US citizen, married or unmarried at least 25)." },
  "I-600A": { cites: ["8 CFR 204.3"], rules: "Advance processing of the parents' suitability before identifying a child; home study, fingerprints, approval valid for a limited period; then I-600." },
  "I-800": { cites: ["8 CFR 204.301", "8 CFR 204.313"], rules: "Hague Convention adoptee: child under 16, Convention country, the country's competent authority found the child eligible and the adoption in the child's best interest, birth parents' consents, approved I-800A." },
  "I-800A": { cites: ["8 CFR 204.309"], rules: "Suitability of US citizen adoptive parents for a Convention adoption: accredited provider home study, fingerprints, criminal history disclosure, approval valid for the stated period." },
  "I-817": { cites: ["8 CFR 236.10"], rules: "Family Unity: spouse or unmarried child of a legalized alien under IRCA, residing in the US since the stated date in the regulation, not inadmissible on the listed grounds. Narrow and historic; check the dates." },

  // Green card
  "I-485": { cites: ["INA 245(a)", "INA 245(c)", "INA 245(k)", "8 CFR 245.1", "8 CFR 245.2"], rules: `1. Inspected and admitted or paroled (INA 245(a)); entry without inspection bars adjustment unless 245(i) applies.
2. Eligible for an immigrant visa and a visa immediately available (priority date current under the chart USCIS uses that month); approved or concurrently filed petition.
3. Not barred by INA 245(c): unauthorized employment, failure to maintain status, status violations (immediate relatives of citizens are exempt from (c)(2), (7), (8); employment based applicants may use 245(k) if violations total 180 days or less since the last lawful admission).
4. Admissible (INA 212(a)): criminal, health (I-693), public charge (I-864 where required), fraud or misrepresentation, unlawful presence bars only on departure, prior removal, false claim to citizenship (no waiver). Waivers where available.
5. Discretion. Traps: overstay by a preference applicant, unauthorized work, a prior misrepresentation in a visa application, a crime with no waiver.` },
  "I-485 Supplement A": { cites: ["INA 245(i)", "8 CFR 245.10"], rules: "245(i): beneficiary of a petition or labor certification filed on or before April 30, 2001 (approvable when filed); if filed after January 14, 1998, physically present on December 21, 2000; $1,000 penalty. Lets an applicant adjust despite entry without inspection or status violations; does not waive other grounds such as the permanent bar." },
  "DS-260": { cites: ["22 CFR 42.62", "22 CFR 42.65", "INA 212(a)"], rules: "Immigrant visa through the National Visa Center and a consulate: approved petition, current priority date, civil documents for the country (birth, marriage, police certificates), affidavit of support, medical, interview. Inadmissibility applies at the consulate, including unlawful presence bars triggered by departure (212(a)(9)(B)) unless a provisional waiver was approved. Traps: departure triggering a bar, missing police certificate, 221(g) holds." },
  "I-693": { cites: ["8 CFR 232.2", "INA 212(a)(1)"], rules: "Medical examination by a USCIS designated civil surgeon; required vaccinations; health grounds of inadmissibility (communicable disease, missing vaccinations, physical or mental disorder with harmful behavior, drug abuse); validity rules for the signature (check current)." },
  "I-765": { cites: ["8 CFR 274a.12"], rules: "Work permit: identify the exact eligibility category (8 CFR 274a.12(a) incident to status, (c) on application) and its evidence; asylum EAD timing rules; automatic extension rules for certain categories (check current). The category must match the underlying basis." },
  "I-131": { cites: ["8 CFR 223.2", "8 CFR 212.5"], rules: "Travel document: advance parole for adjustment applicants and others, re entry permit for LPRs, refugee travel document, parole. Travel on advance parole by an adjustment applicant does not trigger the unlawful presence bar (Matter of Arrabally and Yerrabelly) but leaving without it abandons the application (except H, L, K, V holders)." },
  "I-90": { cites: ["8 CFR 264.5"], rules: "Replace or renew a ten year card. Conditional residents with expiring two year cards do not use I-90; they file I-751 or I-829. Card lost, stolen, damaged, wrong data, name change, turning 14. Traps: abandoned residence (long absences), criminal history that makes the person removable." },
  "I-407": { cites: ["8 CFR 1.4"], rules: "Voluntary record of abandonment of LPR status; irreversible as a practical matter; advise on tax and benefit consequences and on the alternative of contesting abandonment." },
  "I-131 re-entry": { cites: ["8 CFR 223.2"], rules: "1. A permanent resident (or conditional resident) physically in the US at filing. 2. Biometrics in the US before departure (the permit can be delivered to a consulate). 3. Validity up to two years; further permits are limited after long absences. 4. Effect: an absence of over a year no longer, by itself, counts as abandonment and the person can return without an SB-1; it does not prevent abandonment if other facts show it, and does not preserve continuous residence for naturalization (N-470)." },
  "SB-1": { cites: ["22 CFR 42.22"], rules: "1. A lawful permanent resident at departure. 2. Left with the intent to return and kept that intent throughout. 3. The stay beyond one year (or beyond the re entry permit) was caused by circumstances beyond the person's control (illness, a government restriction), not choice. 4. Continued ties to the US (taxes filed as a resident, property, family, employment). 5. Immigrant visa eligibility at the consulate, including medical and inadmissibility. Consular discretion; a denial leaves a new immigrant petition as the route." },
  "I-912": { cites: ["8 CFR 106.3"], rules: "Fee waiver: only for the forms that allow it; means tested benefit, income at or below 150 percent of poverty guidelines, or financial hardship; full documentation." },
  "I-687": { cites: ["8 CFR 245a.2"], rules: "Historic IRCA legalization; temporary residence; class action settlement eligibility. Check eligibility dates; rarely applicable." },
  "I-698": { cites: ["8 CFR 245a.3"], rules: "Adjust from IRCA temporary to permanent residence; continuous residence, English and civics or study, filing within the period. Historic." },
  "I-694": { cites: ["8 CFR 245a.20"], rules: "Appeal of an IRCA legalization denial to the Administrative Appeals Office within 30 days." },

  // Humanitarian
  "I-589": { cites: ["INA 208", "INA 241(b)(3)", "8 CFR 208.4", "8 CFR 208.13", "8 CFR 208.16", "8 CFR 208.18"], rules: `1. One year filing deadline from last arrival (INA 208(a)(2)(B)), unless changed circumstances or extraordinary circumstances and filing within a reasonable time (8 CFR 208.4). Does not apply to withholding or CAT.
2. Refugee: past persecution or a well founded fear of future persecution (reasonable possibility) on account of race, religion, nationality, political opinion or a particular social group, with that ground at least one central reason (INA 208(b)(1)(B)(i)); persecutor is the government or one it is unable or unwilling to control; particular social group must be immutable, particular and socially distinct. Past persecution creates a presumption the government can rebut (changed conditions, internal relocation; 8 CFR 208.13(b)).
3. Credibility under the REAL ID Act: totality, consistency, detail and corroboration where reasonably available.
4. Bars (INA 208(b)(2)): persecutor, particularly serious crime, serious nonpolitical crime, security, terrorism, firm resettlement; prior asylum application denied.
5. Discretion. Withholding (INA 241(b)(3)): clear probability, more likely than not, no one year limit. CAT (8 CFR 208.16 to 208.18): more likely than not to be tortured by or with the acquiescence of a public official, no nexus required. Traps: inconsistencies between the declaration, interview and documents; gang or domestic violence groups pleaded without particularity; missed deadline.` },
  "I-914": { cites: ["8 CFR 214.202", "8 CFR 214.206", "8 CFR 214.207(a)", "8 CFR 214.207(b)", "8 CFR 214.208", "8 CFR 214.209", "INA 101(a)(15)(T)"], rules: `The T visa rules are at 8 CFR 214.200 to 214.216 (2024 rule); 8 CFR 214.11 now only points there, so decisions applying the old 214.11 may state a narrower test. Eligibility (8 CFR 214.202), each element in turn:
1. Victim of a severe form of trafficking (8 CFR 214.206): labor trafficking (recruitment, harboring, transport, provision or obtaining by force, fraud or coercion for involuntary servitude, peonage, debt bondage or slavery) or sex trafficking.
2. Physically present in the US (or American Samoa, the CNMI or a port of entry) on account of the trafficking (8 CFR 214.207(a)): currently trafficked; liberated by law enforcement or escaped before filing; trafficked in the past with present presence directly related to it, whatever the time since; or allowed entry to take part in an investigation or prosecution. If the person departed or was removed after the trafficking, also 8 CFR 214.207(b): reentry from continued victimization, a new trafficking incident, reentry for or presence on account of participation in investigative or judicial processes, or return and treatment or services for the victimization not available abroad. Delay since escape is not fatal by itself; analyze the person's statement, trauma and services (214.207(c)).
3. Complied with any reasonable request for assistance from law enforcement (8 CFR 214.208); at a minimum a report to an agency with jurisdiction, a single contact may suffice; reasonableness judged on the listed factors; exempt if under 18 at the time of an act of trafficking, excepted if unable because of physical or psychological trauma (credible evidence required). An LEA declaration helps but is not required.
4. Extreme hardship involving unusual and severe harm on removal (8 CFR 214.209), using traditional extreme hardship factors and trafficking specific ones (care not available, consequences of victimization, loss of access to US courts, penalties or stigma at home, re victimization, trafficker reach, conflict, economic harm); hardship to others counts only through its effect on the applicant.
5. Not barred as a trafficker (214.202(e)); inadmissibility waivable by I-192 under INA 212(d)(13). Annual cap of 5,000 T-1 (8 CFR 214.210). Family members (T-2 to T-6: spouse, children, and for victims under 21 parents and unmarried siblings under 18, or any family facing present danger of retaliation) through I-914 Supplement A.` },
  "I-918": { cites: ["8 CFR 214.14", "INA 101(a)(15)(U)", "INA 214(p)"], rules: `1. Victim of qualifying criminal activity (listed crimes or similar activity, attempt, conspiracy, solicitation) that occurred in the US or violated US law.
2. Substantial physical or mental abuse as a result (8 CFR 214.14(b)(1)): nature of the injury, severity of the conduct and harm, duration, permanent or serious harm, aggravation of pre existing conditions; a series of acts may add up. Diagnoses alone are not enough when the details show lesser harm; inconsistencies between the police report, certification and later accounts weigh heavily.
3. Possesses information and has been, is, or is likely to be helpful: I-918 Supplement B signed by a certifying official (agency head or a supervisor specifically designated; 8 CFR 214.14(a)(3)) within six months before filing.
4. Admissibility, with I-192 waiver under 212(d)(14). INA 204(c) does not apply. A relative's approval for the same crime does not bind this petition. Indirect victims and family through I-918 Supplement A.` },
  "I-929": { cites: ["8 CFR 245.24(g)"], rules: "U visa principal's qualifying family member who never held derivative U status: principal has or is adjusting on U status; relationship exists; family member or principal would suffer extreme hardship if the family member is not allowed to remain or join." },
  "I-360 VAWA": { cites: ["8 CFR 204.2(c)", "INA 204(a)(1)(A)(iii)", "INA 204(a)(1)(J)"], rules: `Self petition by an abused spouse (or child, or parent) of a US citizen or LPR. Elements (8 CFR 204.2(c)(1)): qualifying relationship (marriage valid, all prior marriages ended; divorce within two years before filing still qualifies if connected to the abuse; intended marriage to a bigamist counts), eligible for immediate relative or preference classification, resided with the abuser, battery or extreme cruelty during the relationship, good moral character (generally the three years before filing; acts connected to the abuse can be excused), good faith marriage. Any credible evidence (INA 204(a)(1)(J)). Living apart for years does not end a marriage; only a final decree does. Traps: confusing support or custody cases with divorce, no evidence of shared residence, GMC issues.` },
  "I-765V": { cites: ["INA 106"], rules: "Work authorization for abused spouses of certain nonimmigrants (A, E(iii), G, H): admitted in the derivative status, battered or subjected to extreme cruelty by the principal during the marriage, and still in or recently in valid status; evidence of the abuse." },
  "SIJS": { cites: ["8 CFR 204.11", "INA 101(a)(27)(J)"], rules: "Under 21 and unmarried at filing; a juvenile court order (court with jurisdiction over custody or dependency) that declares the child dependent or places custody with an agency or person, finds reunification with one or both parents not viable due to abuse, neglect, abandonment or a similar basis under state law, and that return to the home country is not in the child's best interest; the order must be sought for relief from abuse or neglect, not primarily for immigration (USCIS consent). Factual basis in the order. Age out rules; adjustment through EB-4 with visa availability." },
  "I-821": { cites: ["8 CFR 244.2", "8 CFR 244.4"], rules: "TPS: national of a designated country (or habitual resident if stateless); continuous residence and continuous physical presence since the dates in the current Federal Register notice; registration in the period (late registration only on listed grounds); not barred (any felony or two misdemeanors, persecutor or security bars, firm resettlement); admissible or waived. Designations change: check the current notice." },
  "I-821D": { cites: ["8 CFR 236.22", "8 CFR 236.23"], rules: "DACA: came to the US before age 16; under 31 on June 15, 2012; continuous residence since June 15, 2007; present on June 15, 2012 and at filing; in school, graduated, GED, or honorably discharged veteran; no felony, significant misdemeanor or three or more misdemeanors, not a threat. Court orders limit what USCIS can approve (especially initial requests): check the current status before advising. Renewals file 120 to 150 days before expiry." },
  "I-131 parole": { cites: ["INA 212(d)(5)", "8 CFR 212.5"], rules: "1. Urgent humanitarian reason (medical treatment, a dying relative, protection) or significant public benefit (law enforcement, litigation) (INA 212(d)(5)). 2. Why the person cannot obtain a visa or other route, and why parole is temporary. 3. Financial support (I-134 or program form) and arrangements for return. 4. Security and criminal checks; discretion case by case. 5. Duration tied to the reason; re parole requests before expiry. Program parole is separate (Parole programs)." },
  "I-881": { cites: ["8 CFR 240.60"], rules: "NACARA suspension or special rule cancellation: Guatemalan, Salvadoran (ABC class) or certain former Soviet bloc nationals with the required registration or asylum filing dates, seven years of continuous physical presence, good moral character, extreme hardship to self or qualifying relatives. Historic, specialist." },
  "I-602": { cites: ["8 CFR 207.3"], rules: "Waiver of inadmissibility for a refugee: humanitarian purposes, family unity or public interest; some grounds cannot be waived (controlled substance trafficking, security, persecutor)." },
  "I-590": { cites: ["8 CFR 207.1", "INA 207"], rules: "1. Refugee definition (INA 101(a)(42)): outside the country of nationality, unable or unwilling to return because of persecution or a well founded fear on a protected ground. 2. Access: a priority referral (UNHCR, embassy, NGO), a designated group, or family reunification. 3. Of special humanitarian concern to the US and within the annual ceiling (check current ceiling and program operation). 4. Not firmly resettled in a third country. 5. Admissible or waived (I-602); bars for persecutors. 6. Credibility at the interview. After admission: adjustment after one year (I-485 refugee)." },
  "I-360 Amerasian": { cites: ["8 CFR 204.4"], rules: "Amerasian: born in Korea, Vietnam, Laos, Cambodia or Thailand after December 31, 1950 and before October 22, 1982, fathered by a US citizen; sponsor in the US. Separately, the Vietnam Amerasian Homecoming Act (visa symbols AM1 to AM3) covered children born in Vietnam between January 1, 1962 and January 1, 1976 to US citizen fathers, with their spouses, children and mothers. Both are rare now." },
  "I-854": { cites: ["8 CFR 214.2(t)"], rules: "S visa: requested by a law enforcement agency for a witness or informant with critical reliable information; not filed by the person. Rare and confidential." },

  // Visitors, students, exchange
  "DS-160": { cites: ["INA 214(b)", "22 CFR 41.11"], rules: "Nonimmigrant visa: the applicant must overcome the presumption of immigrant intent (INA 214(b)) for most classes by ties to the home country, purpose of the trip and means; prior overstays, misrepresentation and criminal history are inadmissibility issues. Answers must be truthful and consistent with prior applications." },
  "B-1/B-2": { cites: ["8 CFR 214.2(b)", "INA 214(b)"], rules: "Business (meetings, negotiations, not productive work for a US employer) or pleasure; nonimmigrant intent and a residence abroad; funds. Extensions (I-539) before the I-94 expires with a reason; change of status soon after entry raises misrepresentation questions (the 90 day guidance used by the State Department)." },
  "F-1": { cites: ["8 CFR 214.2(f)"], rules: "Admitted to a SEVP school, full course of study, funds, intent to return; maintain status (full load, authorized employment only, SEVIS record). Reinstatement (8 CFR 214.2(f)(16)) within five months of falling out of status for reasons beyond control. Change of status from B requires care." },
  "M-1": { cites: ["8 CFR 214.2(m)"], rules: "1. Admission to an SEVP certified vocational school for a full course of study, with funds for the whole program. 2. Fixed admission for the program plus 30 days, no duration of status. 3. Cannot change to F-1, and cannot change to H if the M training qualified the person for it. 4. Practical training only after completion, one month per four months of study, up to six months, with I-765. 5. Extensions only for compelling reasons. 6. Maintenance: full time attendance, no unauthorized work." },
  "OPT": { cites: ["8 CFR 214.2(f)(10)", "8 CFR 214.2(f)(11)", "8 CFR 214.2(f)(12)"], rules: "Post completion OPT up to 12 months related to the field, filed up to 90 days before and 60 days after program end with DSO recommendation; unemployment limits; STEM OPT 24 month extension with an E-Verify employer, I-983 training plan and a qualifying STEM degree; cap gap for H-1B." },
  "J-1": { cites: ["22 CFR 62", "INA 212(e)"], rules: "1. Designated sponsor and program category (research scholar, student, physician, au pair, intern, trainee) with its own rules on duration and work. 2. DS-2019 and SEVIS fee; funding; intent to return. 3. The two year home residency requirement (INA 212(e)) if the program was government funded, the skill is on the Exchange Visitor Skills List for the home country, or the person came for graduate medical education; it bars H, L, K and immigrant status until satisfied or waived. 4. Maintenance: stay within the program, insurance, sponsor reporting; 12 and 24 month bars on repeat research scholar programs. 5. Waivers through I-612 and DS-3035." },
  "I-539": { cites: ["8 CFR 214.1(c)(4)"], rules: "1. Filed before the current authorized stay expires (late filings excused only for extraordinary circumstances beyond the person's control, 8 CFR 214.1(c)(4)). 2. The person maintained status and is not barred from extending or changing (J subject to 212(e) cannot change except to A, G or T, U; K, C, D, S and visa waiver entrants cannot; M students cannot change to F). 3. The new or extended stay meets the class's own requirements, with funds and a residence abroad where intent matters. 4. No misrepresentation at entry: a change of status soon after entry raises preconceived intent questions. 5. Admissibility. 6. Pending I-539 and the I-94 expiry: the person accrues no unlawful presence while a timely, non frivolous request is pending, but is not in status if denied." },
  "I-102": { cites: ["8 CFR 264.6"], rules: "Replace or correct an I-94: USCIS corrects its own errors; CBP errors go to CBP deferred inspection." },
  "I-612": { cites: ["INA 212(e)", "8 CFR 212.7(c)"], rules: "Waiver of the J-1 two year home residency rule: no objection statement (not for graduate medical training), interested government agency, Conrad 30 state program for physicians, persecution, or exceptional hardship to a US citizen or LPR spouse or child (higher than extreme hardship). Starts with the State Department waiver application (DS-3035); the State Department recommends and USCIS decides." },
  "A, G and NATO": { cites: ["8 CFR 214.2(a)", "8 CFR 214.2(g)"], rules: "Diplomatic and international organization status; employment of dependents; adjustment requires the I-508 waiver of privileges and immunities and sometimes I-566; special immigrant G-4 retirees. Specialist." },
  "I visa": { cites: ["8 CFR 214.2(i)"], rules: "Representative of foreign media, working for a media organization with a home office abroad, engaged in news gathering; reciprocity; not for commercial or entertainment productions." },

  // Waivers
  "I-601": { cites: ["INA 212(h)", "INA 212(i)", "INA 212(a)(9)(B)(v)", "8 CFR 212.7"], rules: `1. Identify each ground and the waiver that covers it: 212(i) fraud or misrepresentation (extreme hardship to a US citizen or LPR spouse or parent; children do not count); 212(a)(9)(B)(v) unlawful presence (spouse or parent); 212(h) crimes (spouse, parent, son or daughter; or 15 years since the conduct with rehabilitation and no threat; LPRs with an aggravated felony or under seven years' residence are barred; violent or dangerous crimes need exceptional and extremely unusual hardship, 8 CFR 212.7(d)). Other waivers: 212(g) for health grounds (vaccinations, communicable disease, with conditions), 212(d)(11) for smuggling a spouse, parent, son or daughter, 212(d)(12) for civil document fraud. Some grounds cannot be waived (false claim to citizenship, controlled substance trafficking, most drug offenses beyond 30 grams of marijuana).
2. Extreme hardship to the qualifying relative beyond the usual consequences of removal (Matter of Cervantes-Gonzalez; Matter of Pilch), considered individually and in the aggregate (Matter of Ige). Without a sworn statement of the relative's intent to stay or relocate, both separation and relocation must be shown; failing either fails the requirement (Policy Manual 9 B.4(B)). Assertions need evidence (medical, financial, country conditions).
3. Discretion, separate from hardship: weigh the ground and its circumstances, other violations and criminal history against family ties, length of residence, employment, rehabilitation (Matter of Mendez-Moralez). Traps: hardship to the applicant counted, family support available ignored, discretion skipped.` },
  "I-601A": { cites: ["8 CFR 212.7(e)", "INA 212(a)(9)(B)(v)"], rules: "Provisional unlawful presence waiver before the consular interview: physically present in the US, at least 17, an approved immigrant petition (or selected diversity winner) and the State Department fee paid, only unlawful presence as a ground (any reason to believe another ground applies leads to denial), not in proceedings unless administratively closed, extreme hardship to a US citizen or LPR spouse or parent, discretion. Does not cover the permanent bar (212(a)(9)(C)) or prior removal (need I-212)." },
  "I-212": { cites: ["8 CFR 212.2", "INA 212(a)(9)(A)", "INA 212(a)(9)(C)"], rules: "Permission to reapply after removal: discretionary weighing of the reasons for removal, recency, immigration and criminal history, family ties, hardship, rehabilitation (Matter of Tin; Matter of Lee). Persons under the permanent bar of 212(a)(9)(C) (reentry or attempted reentry without inspection after removal or after one year of unlawful presence) must remain outside the US for ten years before consent can be granted (Matter of Torres-Garcia). Can be filed with I-601 or at a consulate." },
  "I-192": { cites: ["INA 212(d)(3)", "INA 212(d)(13)", "INA 212(d)(14)", "8 CFR 212.4"], rules: "Advance permission to enter as a nonimmigrant despite inadmissibility (212(d)(3)(A), Matter of Hranka: risk of harm, seriousness of past violations, reasons for entry); also the waiver vehicle for T (212(d)(13)) and U (212(d)(14), national or public interest) applicants." },
  "I-193": { cites: ["8 CFR 212.1"], rules: "Waiver of passport or visa for a returning resident or in an unforeseen emergency; requested at the port of entry; narrow." },
  "I-191": { cites: ["8 CFR 1212.3"], rules: "Former 212(c) relief for LPRs with pleas before April 24, 1996 (St. Cyr); seven years of lawful unrelinquished domicile; discretion. Historic, specialist." },
  "I-690": { cites: ["8 CFR 245a.18"], rules: "Waiver of inadmissibility for IRCA legalization applicants: humanitarian purposes, family unity or public interest. Historic." },
  "I-945": { cites: ["8 CFR 213.1"], rules: "Public charge bond offered at USCIS discretion: check whether the current public charge rule uses bonds and the amount set." },
  "I-356": { cites: ["8 CFR 213.1"], rules: "Request to cancel a public charge bond: the immigrant naturalized, died, departed permanently, or reached the required quarters of work or five years as an LPR (check current rule)." },

  // Citizenship
  "N-400": { cites: ["INA 316", "INA 319", "8 CFR 316.2", "8 CFR 316.5", "8 CFR 316.10", "INA 312"], rules: `1. Lawful permanent resident, lawfully admitted (status obtained by fraud or error defeats naturalization: Matter of Koloamatangi).
2. Five years as an LPR (three if married to and living in marital union with a US citizen spouse who was a citizen for those three years, INA 319(a)); file up to 90 days early.
3. Continuous residence (8 CFR 316.5): an absence of more than six months but less than a year raises a rebuttable presumption of a break; one year or more breaks it (unless an approved N-470 for qualifying work abroad).
4. Physical presence for at least half the period; three months in the state or USCIS district.
5. Good moral character for the statutory period and up to the oath (8 CFR 316.10): permanent bars (murder, aggravated felony after November 29, 1990), conditional bars (crimes, false testimony to obtain a benefit, unpaid child support, failure to file taxes, failure to register for Selective Service if male 18 to 26, unlawful voting or false citizenship claims), and discretion for conduct before the period.
6. English and civics (exceptions by age and residence; N-648 for disability); attachment to the Constitution. Traps: arrests never disclosed, long trips, removability discovered at the interview.` },
  "N-600": { cites: ["INA 301", "INA 309", "INA 320"], rules: "Certificate of citizenship for a person already a citizen: acquisition at birth abroad (INA 301 or 309 under the law in force at birth: parent's citizenship and required physical presence before the birth; legitimation for children of fathers) or derivation (INA 320 from February 27, 2001: under 18, LPR, in the legal and physical custody of a citizen parent; the former section 321 rules, since repealed, for those who turned 18 before then). Prove each element with documents." },
  "N-600K": { cites: ["INA 322", "8 CFR 322.2"], rules: "Child residing abroad of a US citizen parent: under 18, in the legal and physical custody of the citizen parent, temporarily present in the US on lawful admission for the interview, parent (or a citizen grandparent) met five years of physical presence, two after age 14." },
  "N-336": { cites: ["8 CFR 336.2", "INA 336"], rules: "1. Filed within 30 days of the denial (33 if mailed), with the fee. 2. A different officer of equal or higher grade reviews the case de novo and may hold a new interview and retest English and civics. 3. Address each ground of the denial with evidence; new evidence may be submitted. 4. If the denial is affirmed, de novo review in district court under INA 310(c) within 120 days (1421(c) action). 5. Not available for denials for lack of prosecution, where a motion to reopen is the route." },
  "N-470": { cites: ["INA 316(b)", "8 CFR 316.5(d)"], rules: "Preserve residence for naturalization for work abroad for the US government, a qualifying American firm or international organization, or religious work: one year of uninterrupted physical presence after becoming an LPR before filing, and filed before the absence of a year." },
  "N-565": { cites: ["8 CFR 343a.1"], rules: "Replacement naturalization or citizenship document: lost, mutilated, destroyed, name or gender change, or USCIS error." },
  "N-648": { cites: ["8 CFR 312.2(b)"], rules: "Disability exception to English and civics: a licensed physician or psychologist explains the medically determinable impairment, how it prevents learning, and the diagnosis methods; must last 12 months or more; inconsistent or conclusory forms are rejected." },
  "N-426": { cites: ["INA 328", "INA 329"], rules: "1. Service certified by the military branch on N-426 as honorable. 2. INA 328: one year of honorable service at any time, as a permanent resident, with filing during service or within six months after; residence and presence requirements are waived for those who file in time. 3. INA 329: service during a designated period of hostilities, with no residence or physical presence requirement and no need to be a permanent resident if enlisted in the US. 4. Good moral character, English and civics, attachment. 5. Revocation if separated other than honorably before five years of service (INA 328(f), 329(c))." },
  "N-644": { cites: ["INA 329A"], rules: "Posthumous citizenship for a person who died from injury or disease from active duty service in designated hostilities; filed by next of kin within two years of death." },
  "N-300": { cites: ["8 CFR 334.11"], rules: "Declaration of intention to naturalize; rarely needed, sometimes required by states or employers." },

  // Responses, motions, appeals
  "RFE": { cites: ["8 CFR 103.2(b)(8)", "8 CFR 103.2(b)(11)"], rules: "Answer every point in the order raised, with evidence, within the deadline (no extensions; up to 12 weeks for most RFEs); submit all requested evidence at once (partial responses are decided on the record). Identify each regulatory requirement behind the request and show how the evidence meets it; do not change the material facts of the petition (a petition cannot be made approvable by changing the job or duties after filing, Matter of Izummi). Late responses are not considered." },
  "NOID": { cites: ["8 CFR 103.2(b)(8)", "8 CFR 103.2(b)(16)"], rules: "1. Read each ground the notice states and the regulation behind it. 2. Deadline: as stated (often 30 days, three more if mailed), no extensions. 3. Derogatory information the applicant did not know of must be disclosed and the applicant given a chance to rebut it (8 CFR 103.2(b)(16)(i)); rebut it with documents, not argument. 4. Respond with all evidence at once; partial responses are decided on the record. 5. Weigh withdrawal against denial: a denial on fraud findings follows the person; a withdrawal does not cure fraud findings already made. 6. Preserve the record for motion or appeal." },
  "NOIR": { cites: ["8 CFR 205.2"], rules: "Notice of intent to revoke an approved petition: good and sufficient cause shown by the record at the time of the notice (Matter of Ho, Matter of Estime); rebut each ground; derivative consequences for later benefits." },
  "I-290B": { cites: ["8 CFR 103.3", "8 CFR 103.5"], rules: "Appeal to the AAO (where it has jurisdiction) or motion: 30 days from the decision (33 if mailed). Motion to reopen states new facts with evidence; motion to reconsider shows the decision was wrong in law or policy on the record at the time. On appeal identify the error; new evidence the petitioner was asked for and did not provide may be excluded (Matter of Soriano). Ineffective assistance claims need the Lozada requirements. The AAO reviews de novo. A case certified to a higher authority (I-290C) allows a brief within the stated time." },
  "I-824": { cites: [], rules: "Action on an approved petition or application: duplicate approval notice or notify a consulate, or request the follow to join process for derivatives of a person who adjusted." },
  "221(g)": { cites: ["INA 221(g)"], rules: "1. Read the refusal sheet: missing documents or administrative processing (security checks, a 214(b) or 212(a) issue under review). 2. Submit exactly what was requested, by the consulate's method, and keep proof. 3. Administrative processing has no fixed timeline; follow up with the consulate and the Visa Office public inquiry form. 4. After one year without overcoming the refusal, immigrant visa applicants may need to restart and the petition may be returned to USCIS. 5. Petition returned for revocation review leads to a NOIR at USCIS. 6. Mandamus only after unreasonable delay, with consular nonreviewability limiting review of the decision itself." },
  "Consular reconsideration": { cites: ["22 CFR 42.81", "22 CFR 41.121"], rules: "A refused applicant may submit additional evidence within one year to overcome the refusal; consular nonreviewability limits challenges; advisory opinions from the Visa Office on legal questions." },
  "Expedite": { cites: ["8 CFR 103.2"], rules: "USCIS expedite criteria (check current): severe financial loss, urgent humanitarian reasons, nonprofit furthering US cultural or social interests, government interests, USCIS error; documented proof of the urgency." },
  "Case inquiry": { cites: ["8 CFR 103.2"], rules: "Case outside normal processing times: e-Request or contact center, then the CIS Ombudsman (Form DHS-7001) or a congressional inquiry; mandamus for unreasonable delay." },

  // Court and enforcement
  "Removal defense": { cites: ["INA 240", "8 CFR 1240.10"], rules: "Pleadings to the NTA's allegations and charge; DHS bears the burden of removability by clear and convincing evidence for admitted persons; the respondent must show eligibility for relief (asylum, withholding, CAT, cancellation, adjustment, voluntary departure). Check the NTA for defects and stop time issues (Pereira; Niz-Chavez)." },
  "EOIR-42A": { cites: ["INA 240A(a)"], rules: "LPR cancellation: LPR for at least five years; seven years of continuous residence after any admission, stopped by the NTA or by committing a specified offense (stop time rule); no aggravated felony conviction; discretion weighing equities against adverse factors (Matter of C-V-T-). One time relief." },
  "EOIR-42B": { cites: ["INA 240A(b)(1)"], rules: "Non LPR cancellation: ten years of continuous physical presence (stopped by a complete NTA or a specified offense; departures over 90 days or 180 in total break it), good moral character for ten years, no conviction under listed grounds, exceptional and extremely unusual hardship to a US citizen or LPR spouse, parent or child (well beyond what is normally expected; Matter of Monreal; Matter of Recinas); annual cap; discretion." },
  "Bond": { cites: ["INA 236(a)", "INA 236(c)", "8 CFR 1236.1"], rules: "Bond redetermination: the person must show they are not a danger and are likely to appear (Matter of Guerra factors: ties, employment, criminal history, immigration history); mandatory detention under 236(c) for certain crimes (Joseph hearing if the classification is wrong); arriving aliens are generally not bond eligible." },
  "Motion to reopen": { cites: ["8 CFR 1003.2", "8 CFR 1003.23", "INA 240(c)(7)"], rules: "One motion to reopen within 90 days of the final order, with new material evidence not available earlier and the relief application; exceptions for changed country conditions (asylum), in absentia orders (180 days for exceptional circumstances; any time for lack of notice), equitable tolling. Motion to reconsider within 30 days, showing legal or factual error. Ineffective assistance: Matter of Lozada." },
  "EOIR-26": { cites: ["8 CFR 1003.3", "8 CFR 1003.38"], rules: "1. Timely notice of appeal within 30 calendar days of the immigration judge's decision (received, not mailed), fee or EOIR-26A fee waiver request. 2. State specific reasons in the notice; a vague notice can be summarily dismissed (8 CFR 1003.1(d)(2)(i)(A)). 3. Brief by the BIA's schedule after transcripts; extension requests within the deadline. 4. Standard of review: facts, including credibility, for clear error; law, discretion and judgment de novo (8 CFR 1003.1(d)(3)); no new evidence on appeal, but a motion to remand with new evidence is possible. 5. Stay: automatic for most appeals of removal orders, not for bond appeals. 6. Possible results: affirmance without opinion, remand, or a written decision." },
  "EOIR-29": { cites: ["8 CFR 1003.3"], rules: "Appeal to the BIA from certain DHS decisions (for example denials of I-130 petitions), filed with the DHS office within 30 days." },
  "I-246": { cites: ["8 CFR 241.6"], rules: "1. A final order of removal and a request to ICE for a temporary stay. 2. Factors: humanitarian reasons (serious illness, a US citizen child with special needs), pending relief (a U or T application, a motion to reopen, an I-130 with I-601A plans), length of residence, criminal history, compliance with supervision. 3. Discretionary and not appealable; a denial means removal may proceed. 4. A stay from the BIA or a court of appeals may be needed alongside a pending motion or petition for review." },
  "Prosecutorial discretion": { cites: ["INA 240"], rules: "Requests to ICE or DHS counsel to dismiss, close or not pursue a case; based on current enforcement priorities (check current guidance), equities and criminal history." },
  "Detention": { cites: ["INA 236", "INA 241", "8 CFR 287.7"], rules: "1. Identify the statute: INA 236(a) discretionary detention (bond eligible), 236(c) mandatory detention for listed criminal and terrorism grounds (Nielsen v. Preap, 586 U.S. 392 (2019): applies even if not detained immediately on release), 235(b) for arriving aliens and those in expedited removal (parole only), 241 after a final order. 2. Release options: bond before the immigration judge (236(a)), ICE parole (235(b), 212(d)(5)), release on recognizance, alternatives to detention. 3. A Joseph hearing challenges whether 236(c) applies. 4. Post order: custody reviews and Zadvydas. 5. ICE detainers (I-247) ask a jail to hold for up to 48 hours; they are requests, and many localities limit compliance. 6. Habeas for prolonged or unlawful detention. Conditions, access to counsel and transfers." },
  "Expedited removal": { cites: ["INA 235(b)(1)", "8 CFR 208.30", "8 CFR 208.31"], rules: "1. Who is subject: arriving aliens and others the current designation covers (check current scope of expedited removal), charged under 212(a)(6)(C) or (7). 2. Fear: a person who expresses fear or intent to seek asylum is referred for a credible fear interview; the standard is a significant possibility of establishing eligibility for asylum, withholding or CAT (INA 235(b)(1)(B)(v), 8 CFR 208.30). 3. Reasonable fear for reinstated orders and 238(b) orders: a reasonable possibility of persecution or torture (8 CFR 208.31). 4. Negative findings: review by an immigration judge on request, usually within days; no further appeal (DHS v. Thuraissigiam, 591 U.S. 103 (2020)). 5. Positive findings lead to full proceedings or asylum merits interviews. Check current asylum bars and rules applied at the screening stage, which change." },
  "Voluntary departure": { cites: ["INA 240B", "8 CFR 1240.26"], rules: "1. Pre conclusion (INA 240B(a)): requested before or at the master hearing, no aggravated felony or terrorism ground, concede removability and waive appeal, up to 120 days. 2. Post conclusion (INA 240B(b)): one year of physical presence before the NTA, five years of good moral character, no aggravated felony or terrorism ground, clear and convincing evidence of means and intent to depart, a valid travel document, a bond of at least $500 posted within five business days, up to 60 days. 3. Failure to depart: civil penalty and a ten year bar on cancellation, adjustment, change of status, registry and voluntary departure (INA 240B(d)). 4. Filing a petition for review or motion to reopen terminates the grant under 8 CFR 1240.26 (check the effect on the bar). 5. Discretion." },

  // Federal court
  "Mandamus": { cites: ["28 U.S.C. 1361"], rules: "1. Jurisdiction: 28 U.S.C. 1361 and the APA's unreasonable delay provision (5 U.S.C. 706(1)); the agency must owe a clear, nondiscretionary duty to act (to adjudicate, not to approve). 2. Unreasonable delay under the TRAC factors (Telecommunications Research and Action Center v. FCC): a rule of reason, any timetable Congress set, whether human health and welfare are at stake, the effect of expediting on other priorities, the interests prejudiced, and no need to find impropriety. 3. Exhaustion: inquiries, ombudsman and congressional contact first, documented. 4. Venue where the plaintiff resides or the agency acts. 5. Remedy is an order to adjudicate; many cases end when the agency decides. Check whether the delay concerns a discretionary act or a jurisdiction stripping provision (INA 242(a)(2)(B))." },
  "APA": { cites: ["5 U.S.C. 706"], rules: "1. Final agency action (Bennett v. Spear: consummation of the decision making process and legal consequences). 2. Reviewability: not committed to agency discretion and not barred by INA 242(a)(2)(B) or other jurisdiction stripping (Patel v. Garland, 596 U.S. 328 (2022) for facts underlying discretionary relief). 3. Exhaustion of available administrative appeals where required. 4. Standard: arbitrary, capricious, an abuse of discretion, or not in accordance with law (5 U.S.C. 706(2)), judged on the administrative record; the agency must have considered the relevant factors and explained its reasons (Motor Vehicle Mfrs. Ass'n v. State Farm). 5. Remedy: vacatur and remand, usually not an order to approve. Statute of limitations six years (28 U.S.C. 2401(a))." },
  "PFR": { cites: ["INA 242"], rules: "1. A final order of removal (or a BIA decision that is final) and the petition filed within 30 days in the court of appeals for the circuit where the immigration judge completed proceedings (INA 242(b)); the deadline is not jurisdictional but is strictly applied (Santos-Zacaria v. Garland, 598 U.S. 411 (2023), on exhaustion). 2. Exhaustion of issues before the BIA. 3. Scope: constitutional claims and questions of law always reviewable (INA 242(a)(2)(D)), including the application of law to settled facts (Guerrero-Lasprilla v. Barr, 589 U.S. 221 (2020)); discretionary denials and facts for discretionary relief largely not (Patel v. Garland); criminal alien bar for some grounds. 4. Stay of removal: the Nken v. Holder factors (likely success, irreparable harm, balance, public interest). 5. Motions to reopen or reconsider need their own petition." },
  "Habeas": { cites: ["28 U.S.C. 2241"], rules: "1. Custody by immigration authorities and a claim that detention violates the Constitution or federal law (28 U.S.C. 2241). 2. Venue in the district of confinement, naming the immediate custodian (Rumsfeld v. Padilla). 3. Claims: prolonged detention without a bond hearing (due process analysis after Jennings v. Rodriguez, 583 U.S. 281 (2018), and circuit law), post order detention beyond the Zadvydas period, unlawful detention under the wrong statute, conditions affecting due process. 4. Bars: review of removal orders goes through petitions for review (INA 242(a)(5), (b)(9)), not habeas. 5. Remedy: release or a bond hearing with the government bearing the burden in some circuits." },

  // Compliance and records
  "I-9": { cites: ["8 CFR 274a.2"], rules: "1. Section 1 completed by the employee by the first day of work, with attestation of status. 2. Section 2 completed by the employer within three business days of hire, after physically examining unexpired original documents from the Lists (or a DHS authorized remote alternative for E-Verify employers in good standing). 3. Reverification before work authorization expires (not for permanent residents or citizens). 4. Retention: three years after hire or one year after termination, whichever is later; available within three business days of a request. 5. Corrections: strike through, initial and date, never backdate. 6. Anti discrimination: no specifying documents, no overdocumentation (INA 274B). E-Verify cases within three days where enrolled." },
  "Worksite enforcement": { cites: ["8 CFR 274a.2"], rules: "1. Notice of Inspection: three business days to produce I-9s and requested records; negotiate scope and time in writing. 2. ICE review: technical or procedural violations (correctable within ten business days after a warning), substantive violations, knowing hire. 3. Results: compliance notice, warning, Notice of Suspect Documents (employees whose documents appear invalid), Notice of Intent to Fine. 4. Penalties weighed on size, good faith, seriousness, unauthorized workers, history; hearing before OCAHO within 30 days of the NIF. 5. Responding to suspect documents without discrimination; no retaliation. 6. Criminal exposure for pattern or practice." },
  "PAF": { cites: ["20 CFR 655.760"], rules: "H-1B public access file within one working day of filing the LCA: LCA, wage rate, actual wage system, prevailing wage source, notice, benefits summary." },
  "Site visit": { cites: ["8 CFR 214.2(h)"], rules: "FDNS site visits check that the job, worksite, wage and duties match the petition; prepare the employer and employee to answer consistently and truthfully." },
  "Global mobility": { cites: ["INA 214"], rules: "Program advice for employers: choose the right category, travel and status compliance, green card timing; apply the relevant category rulebook." },
  "FOIA": { cites: ["5 U.S.C. 552"], rules: "Records requests to the right agency (USCIS, CBP, ICE, OBIM, EOIR, State) with identity verification or consent (G-639 or online); track processing; use for prior filings, entries and criminal or immigration history before filing anything new." },
  "G-884": { cites: ["8 CFR 103.2(b)(5)"], rules: "Request return of original documents submitted to USCIS." },
  "G-1041": { cites: ["8 CFR 103.40"], rules: "Genealogy index search and records requests for deceased individuals." },
  "G-1566": { cites: ["8 CFR 103.7"], rules: "Certificate of non existence of a USCIS record." },
  "AR-11": { cites: ["INA 265"], rules: "Change of address within ten days of moving; failure can be a removable offense in rare cases and causes missed notices. In immigration court the change goes to EOIR on EOIR-33 within five days." },

  // Advice
  "Consultation": { cites: [], rules: "1. Facts first: identity, every entry and exit with the manner of entry, every status held, every application filed with its outcome, every arrest and court case, family members and their status, employment. 2. Records to confirm them (FOIA from USCIS, CBP and EOIR, court dispositions) before filing anything. 3. Bars and grounds: unlawful presence, the permanent bar, misrepresentation, false claims to citizenship, criminal grounds, prior removal orders. 4. Every route the facts allow, each tested against its rulebook, with its timeline and risks. 5. The safest route first, and what not to do (travel, filings that expose the person). 6. Written advice to the client after attorney review." },
  "Criminal consequences": { cites: ["INA 101(a)(43)", "INA 212(a)(2)", "INA 237(a)(2)"], rules: "Categorical approach to the statute of conviction (aggravated felony, crime involving moral turpitude, controlled substance, firearms, domestic violence); definition of conviction (INA 101(a)(48)(A)); Padilla duties; petty offense exception; the record of conviction decides divisible statutes." },
  "Travel advice": { cites: ["INA 212(a)(9)(B)", "8 CFR 245.2(a)(4)"], rules: "1. Status and pending filings: an adjustment applicant needs advance parole (except H, L, K and V holders keeping status); asylum applicants who leave without advance parole abandon the claim; travel to the country of persecution threatens refugee or asylum status. 2. Unlawful presence: departure triggers the three or ten year bar for anyone who accrued it, unless advance parole for adjustment applicants (Matter of Arrabally). 3. Return admissibility: criminal history, a prior removal order (departure under an order executes it), visa validity and new visa requirements. 4. Permanent residents: trips over six months raise continuous residence for naturalization; over a year without a re entry permit raises abandonment. 5. DACA and TPS travel needs prior authorization. 6. Check current travel bans and port practices." },
  "Status planning": { cites: [], rules: "Map current status and expiry, every route to the goal and its timeline (priority dates, caps), maintenance requirements, and risks; apply each route's rulebook." },

  // Codes in the State Department and work permit lists that had no rulebook of their own.
  "H-1C": { cites: ["INA 101(a)(15)(H)"], rules: "Registered nurses in health professional shortage area hospitals; the program expired and no H-1C petitions have been accepted since December 20, 2009. Relevant only to records and past status; current nurse routes are Schedule A immigrant petitions, H-1B for advanced practice positions, and TN." },
  "VI5": { cites: ["INA 201(b)"], rules: "Parent of a US citizen where the parent's own residence came under the Virgin Islands Nonimmigrant Alien Adjustment Act of 1982: a closed historic category; the parent of an adult citizen is now an ordinary immediate relative (I-130)." },
  "Former citizen": { cites: ["INA 324(a)", "INA 327"], rules: "Immigrant visas for former citizens: women who lost citizenship by marriage to a noncitizen before September 22, 1922 (INA 324), and people who lost it by serving in allied foreign armed forces in World War II (INA 327); most may instead regain citizenship by taking the oath. Check first whether the loss was valid under Afroyim and Vance v. Terrazas, since many past losses were not." },
  "SP": { cites: [], rules: "USA PATRIOT Act section 421 special immigrants: beneficiaries of petitions or labor certifications filed before September 11, 2001 that were revoked or terminated because of the attacks, and their families. Historic; relevant to records and old cases." },
  "I-765 compelling": { cites: ["8 CFR 204.5(p)", "8 CFR 274a.12(c)(35)", "8 CFR 274a.12(c)(36)"], rules: "Compelling circumstances work permit: principal beneficiary of an approved EB-1, EB-2 or EB-3 petition, in E-3, H-1B, H-1B1, L-1 or O-1 status or its grace period, whose priority date is not current, showing compelling circumstances (serious illness or disability, employer dispute or retaliation, other substantial harm, or significant disruption to the employer), with no felony or two or more misdemeanors; family members under (c)(36). It gives work authorization but not status, so the person falls out of status once it is used." },

  // Found in the forms the regulations name (8 CFR, 20 CFR 655 and 656, 22 CFR), 2026-11-22.
  "EOIR-40": { cites: [], rules: "Suspension of deportation under former INA 244(a), only in deportation proceedings begun before April 1, 1997: seven years of continuous physical presence, good moral character, and extreme hardship to the person or a US citizen or resident spouse, parent or child (ten years and exceptional hardship for some grounds). NACARA special rule cancellation (I-881) is the related route for ABC class members and certain others." },
  "Carrier fines": { cites: ["INA 273", "8 CFR 280.1"], rules: "Fines on airlines and vessels for bringing passengers without required documents or failing to detain or remove (INA 273 and related sections): Notice of Intention to Fine (I-79), a written defense within the deadline, then appeal to the BIA (EOIR-45). Defenses include documents that appeared valid on reasonable inspection and mitigation for screening programs." },
  "Recognition and accreditation": { cites: ["8 CFR 1292.11", "8 CFR 1292.12"], rules: "EOIR recognition of a nonprofit (EOIR-31): religious, charitable, social service or similar organization, federally tax exempt, providing immigration legal services primarily to low income people, with adequate knowledge, information and experience, including access to an attorney or accredited representative for supervision. Accreditation of its representatives (EOIR-31A): good character and fitness, broad knowledge of immigration law and procedure, training; partial (DHS only) or full (DHS and EOIR); renewal on the regulatory cycle." },
  "I-700": { cites: ["INA 210"], rules: "Special agricultural worker legalization (1986): 90 days of qualifying seasonal agricultural work in the year ending May 1, 1986; the application period ended November 30, 1988. Historic; relevant to old records, work permit category (c)(20) and class settlements." },
  "OCAHO": { cites: ["INA 274A(e)", "INA 274C", "8 CFR 274a.9"], rules: "Administrative hearings before the Office of the Chief Administrative Hearing Officer: employer sanctions under INA 274A (knowing hire or continued employment of unauthorized workers, I-9 paperwork violations, with penalties set by size of business, good faith, seriousness, unauthorized workers involved and history), document fraud under INA 274C, and discrimination under INA 274B. A hearing must be requested within 30 days of the Notice of Intent to Fine or the final order follows; settlement and penalty mitigation are common." },
  "274B discrimination": { cites: ["INA 274B"], rules: "Unfair immigration related employment practices: citizenship status discrimination against protected individuals, national origin discrimination (employers of 4 to 14 employees; larger ones go to the EEOC), unfair documentary practices (requesting more or different documents, or rejecting valid ones, with discriminatory intent), and retaliation. A charge with the Immigrant and Employee Rights Section within 180 days, then OCAHO. Employers: E-Verify and reverification practices are the usual source of claims." },
  "Bond breach": { cites: ["8 CFR 103.6"], rules: "Immigration bonds (delivery bonds on Form I-352, voluntary departure and maintenance of status bonds): a delivery bond is breached when the obligor fails to produce the person after a proper demand; breach is noticed on I-323 and may be appealed to the AAO; defenses include a defective demand notice and substantial performance; cancellation when the conditions are met (departure, residence, death)." },
  "Ineffective assistance": { cites: [], rules: "A claim that former counsel was ineffective, usually inside a motion to reopen: the person's affidavit of the agreement with counsel, notice to former counsel with a chance to respond, and a statement whether a bar complaint was filed and why not (Matter of Lozada, 19 I&N Dec. 637 (BIA 1988)), plus prejudice (Matter of Melgar, 28 I&N Dec. 169 (BIA 2020)) and diligence for equitable tolling of the deadline. Many circuits apply the tolling doctrine to notarios and unlicensed preparers." },
  "INA 289": { cites: ["INA 289", "8 CFR 289.2"], rules: "American Indians born in Canada with at least 50 percent American Indian blood may enter and live in the US freely and are treated as lawfully admitted for permanent residence; proof of blood quantum through tribal and Canadian records; members of the Texas Band of Kickapoo hold the I-872 card. Check removability questions carefully: the protection against removal is contested." },

  // Added 2026-11-22 so the library covers the whole US immigration system, not only the most common filings.
  // Nonimmigrant classes and dependents
  "H-4": { cites: ["8 CFR 214.2(h)(9)(iv)", "8 CFR 274a.12(c)(26)"], rules: "Spouse or unmarried child under 21 of an H principal; status tied to the principal's; a child ages out at 21 (the Child Status Protection Act does not apply to nonimmigrant status). H-4 work permit only for the spouse of an H-1B who has an approved I-140 or an extension under AC21 sections 106(a) and (b); automatic extension rules for H-4 work permits change (check current)." },
  "L-2": { cites: ["INA 214(c)(2)(E)", "8 CFR 214.2(l)(7)"], rules: "Spouse or unmarried child under 21 of an L-1; the spouse is authorized to work incident to status (the I-94 annotated L-2S is evidence of it); a child cannot work on L-2 status; status ends with the principal's." },
  "Dependents": { cites: ["8 CFR 214.2(j)(1)(v)"], rules: "Derivative nonimmigrants: E spouses may work incident to status; J-2 may apply for a work permit when the income is not needed to support the J-1; F-2 and M-2 may not work (F-2 children may attend school, F-2 spouses only avocational study); O-3, P-4, R-2 and TD may not work; N-8 and N-9 are parents and children of certain G-4 special immigrants. Each depends on the principal keeping status; a child ages out at 21 with no Child Status Protection Act protection." },
  "AC21": { cites: ["INA 214(n)", "8 CFR 214.2(h)(2)(i)(H)", "8 CFR 214.2(h)(13)(iii)(C)", "8 CFR 214.2(h)(13)(iii)(D)", "8 CFR 214.2(h)(13)(iii)(E)", "8 CFR 205.1(a)(3)(iii)(C)"], rules: "H-1B beyond six years and portability: one year extensions if a labor certification or I-140 was filed at least 365 days before the six year limit (AC21 106(a)); three year extensions if an I-140 is approved and the person cannot adjust because of per country limits (AC21 104(c)); time spent outside the US can be recaptured with proof of the days abroad. Portability (INA 214(n)) lets a person in H-1B status start with a new employer when the new petition is filed, if lawfully admitted, not employed without authorization since, and the petition is not frivolous. An I-140 approved for 180 days or more is not automatically revoked when the employer withdraws it or closes." },
  "E-2C": { cites: ["8 CFR 214.2(e)(23)"], rules: "CNMI only investor status for long term investors who held CNMI foreign investor status; extensions only within the CNMI; the program's end date has been extended by statute (check current). Related CNMI programs: the CW-1 worker status (I-129CW) and CNMI resident status under the 2019 Long Term Legal Residents Relief Act (check eligibility dates)." },
  "C-1/D": { cites: ["8 CFR 214.2(c)", "8 CFR 214.2(d)", "INA 245(c)", "INA 248(a)"], rules: "C-1 transit and D crewman status: crewmen are admitted for up to 29 days for the vessel or aircraft's stay; neither C nor D can change status, and D crewmen cannot adjust status (the crewman bar in INA 245(c)); crewmen who desert face removal and bars. Check the relief that remains (asylum, consular processing, some immediate relative routes do not cure 245(c)(1))." },
  "BCC": { cites: ["22 CFR 41.32", "8 CFR 212.1(c)"], rules: "Border crossing card for Mexican nationals, a B-1/B-2 visa; entry within the border zone (generally 25 miles, 55 in New Mexico, 75 in Arizona) for up to 30 days without an I-94; travel beyond the zone or longer needs an I-94. Misuse (work, overstays, residence in the US) leads to cancellation and inadmissibility." },
  "ESTA": { cites: ["INA 217", "8 CFR 217.2", "8 CFR 217.4", "INA 245(c)"], rules: "Visa Waiver Program: national of a designated country, ESTA approval, up to 90 days, no extension (satisfactory departure only in an emergency), no change of status (INA 248(a)(4)), adjustment only as an immediate relative (the visa waiver bar in INA 245(c)), waiver of the right to contest removal except through asylum, withholding or CAT. Ineligible after travel to or nationality of listed countries since 2011 (INA 217(a)(12)), prior overstays or refusals; the answer is a B visa. Traps: entering with intent to stay, ESTA denials not disclosed later." },
  "V visa": { cites: ["INA 101(a)(15)(V)", "8 CFR 214.15"], rules: "Spouse or child of a permanent resident who was the beneficiary of an I-130 filed on or before December 21, 2000 that has been pending, or approved and waiting, for three years; work authorized; leads to adjustment. Almost no new cases; check eligibility dates." },
  "FAS": { cites: ["8 CFR 214.7"], rules: "Citizens of the Federated States of Micronesia, the Marshall Islands and Palau may live and work in the US under the Compacts of Free Association without a visa, as habitual residents subject to 8 CFR 214.7; they are nonimmigrants, may be removed on the listed grounds, and may get a work permit card for convenience. They need another route (family, employment) for permanent residence." },

  // Immigrant and adjustment routes
  "Schedule A": { cites: ["20 CFR 656.5", "20 CFR 656.15"], rules: "Precertified occupations filed directly with USCIS with the I-140 and an uncertified ETA-9089: Group I professional nurses (full unrestricted license in the state of employment, or passed the NCLEX, or a CGFNS certificate) and physical therapists (qualified for a license in the state); Group II exceptional ability in the sciences or arts and in the performing arts (widespread acclaim, international recognition). Prevailing wage determination and a notice of filing posted 10 business days (and in house media) are still required. A healthcare worker certificate is needed at the visa or adjustment stage. Ability to pay from the priority date." },
  "Healthcare certificate": { cites: ["INA 212(a)(5)(C)", "8 CFR 212.15"], rules: "Foreign trained nurses, physical and occupational therapists, speech language pathologists and audiologists, medical technologists and technicians, and physician assistants need a certificate from an approved organization (CGFNS VisaScreen or FCCPT) verifying education, license and English, before an immigrant visa, adjustment, or certain nonimmigrant admissions (H-1B, TN). Physicians are not covered by this ground." },
  "Physician NIW": { cites: ["INA 203(b)(2)(B)(ii)", "8 CFR 204.12"], rules: "Physician national interest waiver: agrees to work full time in clinical practice for five years in a designated shortage area or a VA facility, with a letter from a federal agency or state health department that the work is in the public interest; the green card is not approved until the five years are completed and documented. EB-2 eligibility required." },
  "SIV": { cites: ["INA 101(a)(27)"], rules: "Afghan and Iraqi special immigrants: employment by or on behalf of the US government (or ISAF and Resolute Support for Afghans) for the required period, faithful and valuable service shown by a supervisor's letter, an ongoing serious threat where required, Chief of Mission approval, then the petition and visa or adjustment. Translators and interpreters under section 1059 (12 months, small annual numbers). Program deadlines, caps and documentation rules change (check current)." },
  "Priority date": { cites: ["8 CFR 204.5(e)", "INA 204(j)"], rules: "An approved I-140 keeps its priority date for any later EB-1, EB-2 or EB-3 petition unless revoked for fraud, willful misrepresentation, invalidation or revocation of the labor certification, or material error. Downgrading or upgrading means a new I-140. Visa Bulletin: final action dates decide approval; dates for filing decide filing only when USCIS says so that month. Porting under INA 204(j) after 180 days of a pending I-485 to a same or similar job (I-485 Supplement J)." },
  "CSPA": { cites: ["INA 203(h)", "INA 201(f)"], rules: "Child Status Protection Act age: immediate relatives' age freezes at filing (201(f)), and on the parent's naturalization or the beneficiary's change of category; preference and derivative children: age when the visa became available minus the time the petition was pending, and the child must have sought to acquire residence within one year of availability (extraordinary circumstances may excuse). Marriage ends child status. Automatic conversion does not apply to F4 and similar derivatives (Scialabba v. Cuellar de Osorio, 573 U.S. 41 (2014); Matter of Wang)." },
  "DV": { cites: ["INA 203(c)", "22 CFR 42.33"], rules: "Diversity visa: a selected entry; chargeable to an eligible country (or to a spouse's or parent's country of birth under INA 202(b)); high school education or its equivalent (a formal 12 year course), or two years in the last five in an occupation needing at least two years of training (O*NET Job Zone 4 or 5); the entry must have listed the spouse and every child and used compliant photos; the visa must be issued or adjustment approved by September 30 of the fiscal year, with no extension; admissible; adjustment also needs INA 245(a) eligibility. Traps: omitted children, education not equivalent, fiscal year deadline." },
  "Registry": { cites: ["INA 249", "8 CFR 249.2"], rules: "Lawful permanent residence for a person who entered before January 1, 1972, has resided continuously since, has good moral character, is not ineligible for citizenship, and is not inadmissible on criminal, prostitution, drug trafficking, smuggling, terrorism or security grounds; no visa or petition needed. Proof of entry and continuous residence over decades is the hard part." },
  "Cuban adjustment": { cites: ["INA 212(d)(5)"], rules: "Cuban Adjustment Act of 1966: a native or citizen of Cuba inspected and admitted or paroled after January 1, 1959, physically present one year, admissible (with the labor certification and visa document grounds not applying), discretion; a spouse or child living with them qualifies whatever their nationality. Residence dates back 30 months or to arrival if later. Release on recognizance under INA 236 is not parole (Matter of Cabrera-Fernandez, 28 I&N Dec. 747 (BIA 2023)); check the release document." },
  "NACARA 202": { cites: [], rules: "Adjustment for Nicaraguans and Cubans continuously present since December 1, 1995 (section 202 of the Nicaraguan Adjustment and Central American Relief Act of 1997), application deadline March 31, 2000; the implementing regulation (former section 245.13 of title 8) is no longer in the CFR. Still relevant for dependents, reopened cases and records; check whether a timely filing was made." },
  "HRIFA": { cites: ["8 CFR 245.15"], rules: "Haitian Refugee Immigration Fairness Act: Haitians present since December 31, 1995 who filed for asylum, were paroled or met the child categories; deadline March 31, 2000; relevant for dependents and old cases." },
  "LRIF": { cites: [], rules: "Liberian Refugee Immigration Fairness: Liberian nationals continuously present since November 20, 2014, and their spouses and children; the application deadline (December 20, 2021) has passed; relevant for pending and reopened cases." },
  "I-485 refugee": { cites: ["INA 209(a)", "INA 209(c)", "8 CFR 209.1"], rules: "A refugee must apply for residence after one year of physical presence: admitted as a refugee (or follow to join), status not terminated, not already a resident; public charge, labor certification and documentation grounds do not apply; most other grounds can be waived under INA 209(c) for humanitarian purposes, family unity or the public interest, but not drug trafficking or the security and terrorism grounds. Residence dates back to arrival." },
  "I-485 asylee": { cites: ["INA 209(b)", "INA 209(c)", "8 CFR 209.2"], rules: "One year of physical presence after the asylum grant, still a refugee (or the spouse or child of one), not firmly resettled, asylum not terminated, admissible or waived under INA 209(c). Trips to the country of persecution raise re availment and termination questions. Residence dates back one year from approval." },
  "I-485 U": { cites: ["INA 245(m)", "8 CFR 245.24"], rules: "Admitted as U, three years of continuous physical presence since admission (an absence of over 90 days, or 180 in total, breaks it unless the certifying agency justifies it), still in U status at filing, no unreasonable refusal to help law enforcement since admission, not barred by INA 212(a)(3)(E), and presence justified on humanitarian grounds, family unity or the public interest. Discretion; serious crimes weigh heavily. Family members through I-929." },
  "I-485 T": { cites: ["INA 245(l)", "8 CFR 245.23"], rules: "Lawfully admitted as T-1, three years of continuous physical presence since admission (or less if the investigation or prosecution is complete), good moral character throughout, and either compliance with reasonable requests for assistance (or the trauma or under 18 exceptions) or extreme hardship involving unusual and severe harm on removal; admissible or waived. Derivatives adjust with or after the principal." },
  "I-485 VAWA": { cites: ["INA 245(a)", "INA 245(c)", "INA 212(a)(6)(A)(ii)", "INA 212(a)(4)(E)"], rules: "Adjustment on an approved (or concurrently filed, for immediate relatives) VAWA self petition: inspection and admission are not required; entry without inspection is excused where connected to the abuse (INA 212(a)(6)(A)(ii)); public charge does not apply; unlawful presence and the permanent bar have abuse related exceptions and waivers; the INA 245(c) bars do not apply to a person with an approved VAWA self petition (the opening words of 245(c)). Visa availability for preference categories." },
  "I-485 SIJS": { cites: ["INA 245(h)", "8 CFR 245.1(e)(3)"], rules: "A special immigrant juvenile is deemed paroled for adjustment; public charge, labor certification, entry without inspection, certain misrepresentation, stowaway and documentation grounds do not apply; most others can be waived for humanitarian purposes, family unity or the public interest, but not the criminal grounds listed (except a single offense of simple possession of 30 grams or less of marijuana) or security and terrorism grounds. Visa availability in EB-4 is backlogged for some countries; the petition requires the person to stay unmarried." },
  "PIP": { cites: ["INA 212(d)(5)"], rules: "Parole in place for spouses, parents and children of active duty members, reservists and veterans (policy, check current): discretionary, case by case; the parole makes an immediate relative eligible to adjust despite entry without inspection, but does not cure the permanent bar, prior removal orders or criminal grounds. The broader 2024 Keeping Families Together process was vacated by a federal court." },
  "Parole programs": { cites: ["INA 212(d)(5)", "8 CFR 212.5"], rules: "Program parole (Uniting for Ukraine, Afghan re parole, Family Reunification Parole, Central American Minors, and the terminated CHNV process): eligibility, the US supporter's I-134A, re parole and work permits are set by each program's notice and change or end often, frequently through litigation. Check the current notice before advising; parole is not admission, but is a basis for adjustment where the person otherwise qualifies." },
  "DED": { cites: ["8 CFR 274a.12(a)(11)"], rules: "Deferred Enforced Departure is a presidential decision for nationals of a named country; eligibility, dates and work permit extensions come from the current presidential memorandum and Federal Register notice (check current designations); it is not a status and does not lead to residence by itself." },
  "Deferred action": { cites: ["8 CFR 274a.12(c)(14)"], rules: "Discretionary non DACA deferred action (medical, humanitarian, compelling circumstances) from USCIS or ICE; no form, a request with evidence; work permit under (c)(14) with economic necessity; the person accrues no unlawful presence while it lasts but gains no status. Deferred action for special immigrant juveniles and other categories depends on current policy (check current)." },

  // Removal, enforcement and court
  "Reinstatement": { cites: ["INA 241(a)(5)", "8 CFR 241.8", "8 CFR 208.31"], rules: "A prior removal order is reinstated against a person who reentered unlawfully after removal or departure under an order; it cannot be reopened and bars most relief (Fernandez-Vargas v. Gonzales, 548 U.S. 30 (2006)); a reasonable fear interview leads to withholding only proceedings (withholding and CAT, not asylum). Check whether the reentry was in fact unlawful (entry with a visa or parole is not), whether the prior order is valid, and U or T routes with I-212 and I-192." },
  "238(b)": { cites: ["INA 238(b)", "8 CFR 238.1"], rules: "Administrative removal of a person who is not a permanent resident and has an aggravated felony conviction: no hearing before an immigration judge; 10 days to rebut the charge (alienage, conviction, aggravated felony); reasonable fear for withholding and CAT; review only by petition for review. Check whether the person is in fact a resident or the offense is in fact an aggravated felony." },
  "237(a)(1)(H)": { cites: ["INA 237(a)(1)(H)"], rules: "Waiver of removability for fraud or misrepresentation at admission (and some documentation grounds that resulted from it): the spouse, parent, son or daughter of a US citizen or resident, who had an immigrant visa or equivalent and was otherwise admissible at admission; or a VAWA self petitioner. Discretion weighs the fraud against equities. Also covers residence obtained by misrepresentation of marital status in some cases." },
  "VAWA cancellation": { cites: ["INA 240A(b)(2)"], rules: "Battered or subjected to extreme cruelty by a US citizen or resident spouse or parent (or the parent of a child abused by one); three years of continuous physical presence (the notice to appear does not stop it, and absences connected to the abuse do not break it); good moral character in that period; not inadmissible or deportable on the listed criminal, security and marriage fraud grounds, no aggravated felony; extreme hardship to the person, their child or parent. Annual cap; discretion." },
  "Closure and termination": { cites: ["8 CFR 1003.18(c)", "8 CFR 1003.18(d)", "8 CFR 1003.1(l)"], rules: "Administrative closure and termination before the immigration judge and the BIA under the 2024 EOIR rule: closure weighs the listed factors (pending relief with USCIS, likelihood of success, delay, DHS position); termination is required in listed situations (for example no removability charge sustained, or prima facie eligibility for naturalization with DHS consent) and allowed in others (pending relief such as T, U, SIJS or VAWA). Check whether the rule has been changed or enjoined." },
  "UAC": { cites: ["INA 208(b)(3)(C)", "INA 208(a)(2)(E)"], rules: "Unaccompanied children (under 18, no lawful status, no parent or legal guardian available to care for them): USCIS has initial jurisdiction over their asylum claims even in removal proceedings, the one year deadline and safe third country bars do not apply, they go to ORR custody and a sponsor, and SIJS is often available. Determinations of UAC status and their later effect are contested (check current policy)." },
  "Order of supervision": { cites: ["8 CFR 241.5", "8 CFR 241.4", "8 CFR 274a.12(c)(18)"], rules: "Release after a final order when removal is not imminent: conditions of the order of supervision (check ins, address, travel), work permit under (c)(18), post order custody reviews, and release when removal is not reasonably foreseeable after the presumptive six months (Zadvydas v. Davis, 533 U.S. 678 (2001)). Violations lead to detention and criminal penalties." },
  "Illegal reentry": { cites: ["8 U.S.C. 1326"], rules: "Criminal reentry after removal: removed or departed under an order, then entered, attempted to enter or was found in the US without consent; sentence enhancements under 1326(b) for prior convictions; a collateral attack on the removal order needs all three of exhaustion, deprivation of judicial review and fundamental unfairness (1326(d); United States v. Palomar-Santiago, 593 U.S. 321 (2021)). Coordinate with criminal defense counsel." },
  "Post-conviction relief": { cites: ["INA 101(a)(48)(A)"], rules: "A vacated conviction stops counting for immigration only when vacated for a procedural or substantive legal defect, not for rehabilitation or to avoid immigration consequences (Matter of Pickering, 23 I&N Dec. 621 (BIA 2003)); sentence changes count only if based on a legal defect (Matter of Thomas and Thompson, 27 I&N Dec. 674 (A.G. 2019)). Padilla v. Kentucky claims and state vehicles for vacatur; coordinate with criminal counsel." },
  "Asylum termination": { cites: ["8 CFR 208.24"], rules: "USCIS (or the immigration judge) may end asylum for fraud in the application, a fundamental change of circumstances so the person is no longer a refugee, a mandatory bar, protection of another country, or voluntary re availment (return trips, a national passport); notice and an interview first; derivatives can lose status. Adjusting to residence ends this risk but trips back raise the same questions." },
  "Port of entry": { cites: ["INA 235(b)(1)", "8 CFR 235.4", "INA 101(a)(13)(C)"], rules: "Inspection at a port: expedited removal for misrepresentation or missing documents (five year bar), withdrawal of the application for admission as the alternative (no bar), deferred inspection, parole at the port, I-94 corrections with CBP. A returning resident is not seeking admission unless an INA 101(a)(13)(C) exception applies; an I-407 is never required to be signed. Electronic device searches and secondary inspection practice change (check current)." },
  "DHS TRIP": { cites: [], rules: "Redress for travel screening problems (repeated secondary inspection, watchlist misidentification, boarding denials) through DHS TRIP with a redress number; Global Entry and other trusted traveler denials and revocations go to the CBP Trusted Traveler Ombudsman; there is no appeal as of right." },
  "Visa revocation": { cites: ["INA 221(i)", "22 CFR 41.122"], rules: "The State Department may revoke a visa at any time; prudential revocations (for example after an arrest for driving under the influence) usually take effect on departure and do not end status already granted in the US, but revocation is a ground of removability (INA 237(a)(1)(B)) and judicial review is limited. Plan travel and new visa applications around it." },
  "212(f) proclamations": { cites: ["INA 212(f)", "INA 215(a)"], rules: "Presidential suspensions of entry for nationals of listed countries or classes (Trump v. Hawaii, 585 U.S. 667 (2018)): read the proclamation's scope, effective date, exceptions and national interest exceptions; they usually limit visa issuance and entry, not status or adjustment inside the US, unless they say so. Proclamations change often (check current)." },

  // Citizenship
  "319(b)": { cites: ["INA 319(b)", "8 CFR 319.2"], rules: "Expedited naturalization for the resident spouse of a US citizen employed abroad by the US government, an American firm or research institution, a public international organization or a religious body, for at least one year: no residence or physical presence requirement, in the US at naturalization, and intends to reside in the US when the employment ends." },
  "CRBA": { cites: ["INA 301", "INA 309"], rules: "Citizenship at birth abroad under the law in force at birth: one citizen parent with the required physical presence before the birth (five years, two after age 14, for births after November 14, 1986), both citizen parents with one having had a residence, or birth out of wedlock under INA 309 (to a father: blood relationship by clear and convincing evidence, his citizenship at birth, a written agreement of financial support, legitimation or acknowledgment before 18; to a mother: physical presence as set by Sessions v. Morales-Santana, 582 U.S. 47 (2017)). Consular Report of Birth Abroad before 18, then a passport; assisted reproduction rules follow current State Department guidance." },
  "Loss of nationality": { cites: ["INA 349"], rules: "Citizenship is lost only by a listed act done voluntarily with the intent to give up citizenship (Vance v. Terrazas, 444 U.S. 252 (1980); Afroyim v. Rusk, 387 U.S. 253 (1967)); renunciation is done abroad before a consular officer, with a fee and a Certificate of Loss of Nationality; it is irrevocable and has tax consequences outside immigration law. A claim that citizenship was lost earlier is decided by the State Department." },
  "Denaturalization": { cites: ["INA 340"], rules: "Civil revocation in federal court for illegal procurement (any requirement not met when naturalized, such as good moral character) or concealment of a material fact or willful misrepresentation (material if it had a natural tendency to influence the decision: Kungys v. United States, 485 U.S. 759 (1988)); proof must be clear, unequivocal and convincing (Fedorenko v. United States). Criminal route under 18 U.S.C. 1425 requires the false statement to have played a role in obtaining citizenship (Maslenjak v. United States, 582 U.S. 335 (2017)). Derivative citizenship of children may be affected." },

  // Federal court
  "1503 action": { cites: ["8 U.S.C. 1503"], rules: "A person in the US denied a right of a national (often a passport) on the ground that they are not a citizen may sue for a declaratory judgment within five years of the final administrative denial; not available if the question arose in or in connection with removal proceedings; a person abroad first seeks a certificate of identity to travel and be heard." },
  "1447(b) action": { cites: ["INA 336(b)"], rules: "If USCIS has not decided a naturalization application within 120 days after the interview, the applicant may sue in the district court where they live; the court may decide the application or remand it with instructions, and most courts hold USCIS cannot decide while the case is pending." },
  "1421(c) action": { cites: ["INA 310(c)", "8 CFR 336.9"], rules: "After the N-336 hearing upholds a denial, the applicant may seek de novo review in district court within 120 days of that decision; the court makes its own findings and may hold a hearing; the applicant bears the burden on every requirement." },
  "EAJA": { cites: [], rules: "Equal Access to Justice Act fees (28 U.S.C. 2412(d)): a prevailing party in a federal court case against the government, with net worth under the limits, whose position was not substantially justified; application within 30 days of final judgment; hourly rate cap adjusted for cost of living. Not available for administrative removal proceedings (Ardestani v. INS, 502 U.S. 129 (1991))." },

  // Labor and compliance
  "BALCA": { cites: ["20 CFR 656.24", "20 CFR 656.26", "20 CFR 656.41"], rules: "A PERM denial can be met with a request for reconsideration to the certifying officer or a request for review by the Board of Alien Labor Certification Appeals within 30 days; review is on the record before the certifying officer, so evidence not submitted then is generally not considered. Prevailing wage determinations: center director review first, then BALCA. Often a new filing is faster than an appeal." },
  "DOL investigation": { cites: ["20 CFR 655.800", "20 CFR 655.731"], rules: "Wage and Hour investigations of H-1B employers (required wage, benching: paying for nonproductive time when the worker is not working because of the employer, 20 CFR 655.731(c)(7), notice, public access file, H-1B dependent attestations), of H-2A and H-2B employers (29 CFR 501 and 503), with back wages, civil money penalties and debarment. Respond with records; cooperation and corrective payments matter." },
  "Corporate changes": { cites: ["20 CFR 655.730(e)", "8 CFR 214.2(h)(2)(i)(E)"], rules: "Mergers, acquisitions and restructuring: an H-1B successor in interest that assumes the predecessor's immigration obligations needs no new petition if the job is unchanged, but material changes (including a new worksite outside the LCA's area, Matter of Simeio Solutions, 26 I&N Dec. 542 (AAO 2015)) need an amended petition; L-1 status needs the qualifying relationship to survive; PERM and I-140 cases need successor in interest (same job, transfer of the business, Matter of Dial Auto Repair Shop, 19 I&N Dec. 481 (Comm'r 1986)); I-9 can continue for successor employees. Check every worker's status before closing." },
  "Layoffs": { cites: ["8 CFR 214.1(l)(2)", "8 CFR 214.2(h)(4)(iii)(E)", "20 CFR 656.17(k)"], rules: "H-1B, L-1, E, O, TN and E-3 workers have a grace period of up to 60 days (or until the I-94 ends) to change status, transfer or leave; the H-1B employer must offer return transportation and notify USCIS to stop wage liability; PERM filed within six months of layoffs in the occupation must notify and consider the laid off workers; an I-140 approved 180 days or more survives withdrawal. Check STEM OPT reporting and pending green card cases." },
  "I-17": { cites: ["8 CFR 214.3"], rules: "School certification and recertification with the Student and Exchange Visitor Program: bona fide school, approved courses, designated school officials with their SEVIS reporting duties, record keeping, site visits; withdrawal for noncompliance affects every student." },
  "I-910": { cites: ["8 CFR 232.2"], rules: "Civil surgeon designation by USCIS: a licensed doctor of medicine or osteopathy with at least four years of professional experience (not counting residency), in good standing; follows the CDC technical instructions; designation can be revoked." },
  "I-131A": { cites: ["8 CFR 211.1"], rules: "Travel document (carrier documentation) for a permanent resident abroad whose card was lost, stolen or destroyed, or whose absence is under one year (or within a re entry permit): filed with USCIS, then a consular appointment; an absence of over a year without a re entry permit needs the SB-1 returning resident visa instead." },

  // Family
  "Humanitarian reinstatement": { cites: ["INA 204(l)", "8 CFR 205.1(a)(3)(i)(C)"], rules: "After the petitioner dies: under INA 204(l), a beneficiary who lived in the US at the death and continues to can still have the pending or approved petition decided (also derivatives, I-730, T and U derivatives), with a substitute sponsor; otherwise humanitarian reinstatement of an approved I-130 under 8 CFR 205.1(a)(3)(i)(C)(2) is discretionary, weighing ties, hardship, age and delay, and needs a substitute sponsor." },
  "Adopted child": { cites: ["INA 101(b)(1)(E)", "8 CFR 204.2(d)(2)(vii)"], rules: "An adopted child qualifies through an I-130 if adopted before 16 (18 for a natural sibling) and the parent has had two years of legal custody and two years of joint residence with the child (before or after the adoption); otherwise use the orphan or Hague routes. A natural parent can never gain benefits through the adopted child." },
  "Private bill": { cites: [], rules: "A private immigration bill introduced by a member of Congress for one person; rare and slow; the judiciary committees' rules decide whether it is taken up, and a pending bill may support a request to ICE for a stay. Use only when every other route has failed." },

  // Inadmissibility
  "Unlawful presence": { cites: ["INA 212(a)(9)(B)", "INA 212(a)(9)(C)"], rules: "Over 180 days and under one year of unlawful presence then departure: three year bar; one year or more: ten year bar; the bar runs from the departure. Exceptions: time under 18, a pending bona fide asylum application, family unity protection, battered spouses and children (with a connection), T victims; tolling for a timely, non frivolous extension or change filed before the stay expired (INA 212(a)(9)(B)(iv)). Admission for duration of status accrues unlawful presence only after a formal finding (check current policy). Permanent bar (INA 212(a)(9)(C)): more than a year in total of unlawful presence, or a removal, then entry or attempted entry without inspection; consent to reapply only after ten years outside. Advance parole travel does not trigger the bar for adjustment applicants (Matter of Arrabally)." },
  "Public charge": { cites: ["INA 212(a)(4)", "INA 213A"], rules: "Inadmissible if likely at any time to become a public charge, judged on the statutory minimum factors (INA 212(a)(4)(B)): age, health, family status, assets, resources and financial status, education and skills, plus a sufficient I-864 where one is required (a missing or insufficient I-864 is itself a ground). The 2022 rule's regulations (sections 212.20 to 212.23 of title 8) were removed from the CFR on September 18, 2026, so which benefits count and how the factors are weighed now come from the statute and current USCIS guidance (check current). Statutory exemptions remain: refugees, asylees, T, U, VAWA and SIJS applicants, among others." },
  "TRIG": { cites: ["INA 212(a)(3)(B)", "INA 212(d)(3)(B)(i)"], rules: "Terrorism related inadmissibility: broad definitions of terrorist activity and Tier I, II and III organizations; material support has no minimum amount and duress is not a defense in itself (Matter of A-C-M-, 27 I&N Dec. 303 (BIA 2018)); relief only through discretionary exemptions under INA 212(d)(3)(B)(i), group based or situational (for example duress or certain limited support), applied by USCIS, not immigration judges. Many cases are put on hold for exemptions." },
};

/** One rulebook in its four parts, always in the same order, so every case type reads the same way: the law it rests on,
 *  the tests in order, the evidence that proves them, and the traps that sink cases. */
function render(key: string) {
  const r = R[key];
  const [evidence, extraTraps] = EVIDENCE[key] ?? ["", ""];
  // Some rulebooks end their tests with "Traps: ..."; that text moves to the traps part.
  const m = /\s*Traps?:\s*([\s\S]*)$/.exec(r.rules);
  const tests = (m ? r.rules.slice(0, m.index) : r.rules).trim();
  const traps = [m?.[1].trim(), extraTraps].filter(Boolean).join(" ");
  return [
    r.cites.length ? `Law: ${r.cites.join("; ")}.` : "",
    `Tests, in order:\n${tests}`,
    evidence ? `Evidence that proves them: ${evidence}` : "",
    traps ? `Traps that sink these cases: ${traps}` : "",
  ].filter(Boolean).join("\n");
}

/** The rulebook for a case type, given as its code ("EB-1A") or as code and name ("EB-1A Extraordinary ability"), with the
 *  citations whose official text should travel with it. */
export function rulebookFor(type: string | null | undefined): { code: string; text: string; cites: string[] } | null {
  const t = (type ?? "").trim().toLowerCase();
  if (!t) return null;
  // The longest code the type starts with, so "I-485 Supplement A" wins over "I-485".
  const key = Object.keys(R).filter((k) => t === k.toLowerCase() || t.startsWith(`${k.toLowerCase()} `)).sort((a, b) => b.length - a.length)[0];
  if (!key) return null;
  return { code: key, text: `Rulebook for ${key}, Lincoln's summary of the governing law (the official text, where given, governs). Apply these tests in order. ${GENERAL}\n${render(key)}`, cites: R[key].cites };
}

export const RULEBOOK_CODES = Object.keys(R);
/** One rulebook in full, for tests and for the chat's rulebook lookup. */
export const rulebookText = (key: string) => (R[key] ? render(key) : null);

// What else a case can carry besides its type: the issues that bring their own legal tests. Each pattern is narrow on
// purpose, since every rulebook added costs space in the prompt.
const STACK: [RegExp, string][] = [
  [/unlawful presence|three year bar|ten year bar|3 year bar|10 year bar|212\(a\)\(9\)\(B\)/i, "Unlawful presence"],
  [/permanent bar|212\(a\)\(9\)\(C\)|prior removal|was (?:removed|deported)|removal order|deportation order|I-212/i, "I-212"],
  [/212\(i\)|212\(h\)|misrepresentation|I-601\b/i, "I-601"],
  [/I-601A|provisional (?:unlawful presence )?waiver/i, "I-601A"],
  [/arrest|convict|criminal (?:charge|history|record)|guilty plea|probation/i, "Criminal consequences"],
  [/public charge/i, "Public charge"],
  [/material support|terroris/i, "TRIG"],
  [/notice to appear|removal proceedings|immigration court|immigration judge/i, "Removal defense"],
  [/request for evidence|\bRFE\b/i, "RFE"],
  [/notice of intent to deny|\bNOID\b/i, "NOID"],
  [/notice of intent to revoke|\bNOIR\b/i, "NOIR"],
  [/\bage[sd]? out|turns 21|\bCSPA\b/i, "CSPA"],
  [/two year home residency|212\(e\)/i, "I-612"],
  [/advance parole|travel (?:abroad|outside)/i, "Travel advice"],
  [/affidavit of support|I-864/i, "I-864"],
  [/priority date|visa bulletin|retrogress/i, "Priority date"],
  [/expedited removal|credible fear|reasonable fear/i, "Expedited removal"],
  [/marriage fraud|204\(c\)/i, "I-130"],
];

// Official codes worth finding in free text: those with a digit, so "I" or "D" in a sentence never match.
const CODE_INDEX = OFFICIAL_CODES.filter((c) => /\d/.test(c.code) && c.kind !== "work permit");
const codeRe = (c: string) => new RegExp(`(?:^|[^A-Za-z0-9/-])${c.replace(/[()/]/g, "\\$&")}(?![A-Za-z0-9/])`);
const CODE_RES = CODE_INDEX.map((c) => [codeRe(c.code), c] as const);
// Work permit categories are written "(c)(8)" or "c8" on cards and notices.
const EAD_RES = OFFICIAL_CODES.filter((c) => c.kind === "work permit").map((c) => [new RegExp(`(?:category\\s*)?${c.code.replace(/[()]/g, "\\$&")}(?![\\d(])|\\b${c.code.replace(/[()]/g, "")}\\b(?=.{0,40}(?:EAD|work permit|employment authorization))`, "i"), c] as const);

// Rulebooks named by their own code in free text ("H-1B", "EB-2 NIW", "I-918"): only codes with a digit, so plain words
// such as "Consultation" never match, and a longer code wins over the shorter one inside it ("EB-2 NIW" over "EB-2").
const KEY_RES = Object.keys(R).filter((k) => /\d/.test(k)).map((k) => [new RegExp(`(?:^|[^A-Za-z0-9-])${k.replace(/[()/.]/g, "\\$&")}(?![A-Za-z0-9-])`), k] as const);
// Case types usually written by name rather than by form or code.
const ALIASES: [RegExp, string][] = [
  [/\bVAWA\b(?! cancellation)/, "I-360 VAWA"],
  [/national interest waiver|\bNIW\b/i, "EB-2 NIW"],
  [/\bU visa|\bU-1\b|\bU nonimmigrant/i, "I-918"],
  [/\bT visa|\bT-1\b|\bT nonimmigrant/i, "I-914"],
];
function named(text: string): string[] {
  const found: [number, string][] = [];
  for (const [re, k] of [...KEY_RES, ...ALIASES]) { const m = re.exec(text); if (m) found.push([m.index, k]); }
  const keys = [...new Set(found.sort((a, b) => a[0] - b[0]).map(([, k]) => k))];
  return keys.filter((k) => !keys.some((o) => o !== k && o.startsWith(`${k} `)));
}

/** Every rulebook a case touches: its type first, then the official codes and issues found in what is known of it
 *  (summary, issues, the request), up to a size budget. The type's own rulebook always comes first. */
export function rulebooksFor(type: string | null | undefined, context = "", maxChars = 14000): { codes: string[]; text: string; cites: string[] } | null {
  const keys: string[] = [];
  const add = (k: string) => { if (R[k] && !keys.includes(k)) keys.push(k); };
  const primary = rulebookFor(type);
  if (primary) add(primary.code);
  const hay = `${type ?? ""} ${context}`;
  // The case types named in what is known of the case, in the order they first appear, so a consultation about an
  // H-1B or a T visa gets that type's own tests ("Consultation" alone only covers facts, records and bars).
  named(hay).forEach(add);
  for (const [re, c] of CODE_RES) if (re.test(hay)) c.rulebooks.forEach(add);
  for (const [re, c] of EAD_RES) if (re.test(hay)) c.rulebooks.forEach(add);
  for (const [re, k] of STACK) if (re.test(context)) add(k);
  if (!keys.length) return null;
  const parts: string[] = [];
  const cites: string[] = [];
  let size = 0;
  for (const k of keys) {
    const block = `Rulebook for ${k}${parts.length ? " (raised by this case's facts)" : ""}:\n${render(k)}`;
    if (parts.length && size + block.length > maxChars) break;
    parts.push(block);
    cites.push(...R[k].cites);
    size += block.length;
  }
  const used = keys.slice(0, parts.length);
  return { codes: used, text: `Rulebooks, Lincoln's summary of the governing law (the official text, where given, governs). Apply each one's tests in order. ${GENERAL}\n\n${parts.join("\n\n")}`, cites: [...new Set(cites)] };
}
